quests[32045] = { id = 32045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kinder des Wassers", description = "Hier im Tal der Vier Winde sind wir alle Kinder des Wassers. Es nährt uns, es lässt unser Gemüse sprießen und es schenkt uns das Leben.\n\nManche Kreaturen trinken jedoch zu viel vom Wasser des Tals. Sie werden zu groß und müssen beseitigt werden, bevor sie jene in ihrer Nähe noch verletzen.\n\nIch bin nur ein einfacher Steinmeißler, aber Ihr...", sourceObjective = "Tötet Krakor, Donnerkieme und Sukkula.", completion = "Lasst Euch das eine Lektion sein: Trinkt nicht zu viel Wasser.\n\nWas meint Ihr, warum wir so eine große Brauerei haben?", sourceObjectiveStatus = "unverified-source-field" }
