quests[32175] = { id = 32175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkampf des Dunkelmonds!", description = "Seid Ihr bereit, den Mut Eurer Haustiere auf die Probe zu stellen...?", sourceObjective = "Besiegt Jeremy Feasel in einem Haustierkampf.", progress = "Sieh mal einer an. Gut gemacht!", completion = "Ich muss schon sagen – tolle Show.", sourceObjectiveStatus = "unverified-source-field" }
quests[32181] = { id = 32181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Der Kranich", description = "Der uralte Kranich lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jorn Himmelsdeuter bringen, bevor er aufwacht.", sourceObjective = "Bringt den uralten Blutkronenkranich zu Jorn Himmelsdeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[32182] = { id = 32182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Der Tiger", description = "Der Katzen-Älteste lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jorn Himmelsdeuter bringen, bevor er aufwacht.", sourceObjective = "Bringt den Krasariältesten zu Jorn Himmelsdeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[32183] = { id = 32183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Die Krabbe", description = "Die kolossale Krabbe lebt, ist aber betäubt.\n\nIhr solltet sie zu Jorn Himmelsdeuter bringen, bevor sie aufwacht.", sourceObjective = "Bringt die kolossale Zwingzange zu Jorn Himmelsdeuter.", progress = "Willkommen zurück, {name}.", completion = "Zum Einfangen der Bestie war nur einer nötig, um sie wahrhaftig zu bezwingen, sind viele erforderlich.\n\nSprecht wieder mit mir, wenn Ihr genug Verbündete zusammengetrommelt habt. Wir werden die Widerstandsfähigkeit der Krabbe an der Macht der Horde testen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32184] = { id = 32184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Der Kranich", description = "Der uralte Kranich lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jäger Blake bringen, bevor er aufwacht.", sourceObjective = "Bringt den uralten Blutkronenkranich zu Jäger Blake.", progress = "Willkommen zurück, {name}.", completion = "Zum Ergreifen der Bestie war zwar nur ein {race} erforderlich, um sie zu erlegen aber werden viele mehr nötig sein.\n\nRuft ein paar Freunde zusammen und kommt dann wieder zu mir. Wir werden die Anmut des Kranichs gegen den Ruhm der Allianz antreten lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32185] = { id = 32185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Der Tiger", description = "Der Katzen-Älteste lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jäger Blake bringen, bevor er aufwacht.", sourceObjective = "Bringt den Krasariältesten zu Jäger Blake.", progress = "Willkommen zurück, {name}.", completion = "Zum Ergreifen der Bestie war zwar nur ein {race} erforderlich, um sie zu erlegen aber werden viele mehr nötig sein.\n\nRuft ein paar Freunde zusammen und kommt dann wieder zu mir. Wir werden die Kraft des Tigers gegen den Ruhm der Allianz antreten lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32186] = { id = 32186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beute des Bestienmeisters: Die Krabbe", description = "Die kolossale Krabbe lebt, ist aber betäubt.\n\nIhr solltet sie zu Jäger Blake bringen, bevor sie aufwacht.", sourceObjective = "Bringt die kolossale Zwingzange zu Jäger Blake.", progress = "Willkommen zurück, {name}.", completion = "Zum Ergreifen der Bestie war zwar nur ein {race} erforderlich, um sie zu erlegen aber werden viele mehr nötig sein.\n\nRuft ein paar Freunde zusammen und kommt dann wieder zu mir. Wir werden die Ausdauer der Krabbe gegen den Ruhm der Allianz antreten lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32189] = { id = 32189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schäbiger Neuer", description = "Ein seltsamer Typ mit einem spitzen Hut hat heute Morgen versucht, irgendwelche besonderen Samen zu verkaufen. Er behauptete, sie seien magisch.\n\nKonkurrenz an sich stört mich nicht, doch dieser Herr war irgendwie... schäbig. Oh, und er hat ganz mächtig gestunken.\n\nWürdet Ihr ihn bitte genauer unter die Lupe nehmen und herausfinden, ob er eine ehrliche Haut ist? Er ist dort drüben bei Jian Eisentatz und verputzt sämtliche Kostproben.", sourceObjective = "Sprecht mit Barnabas Pfeilmacher auf dem Halbhügelmarkt.", completion = "MHMM... nom... <schlürf>... <grunz>... \n\n<Barnabas schaut auf und Ihr könnt sehen, dass sich eine Menge Melonenkerne in seinem zotteligen Bart verfangen haben. Als er Euch begrüßt, läuft Melonensaft sein Kinn herunter.>\n\nMmf... <hust> Ein Kunde! Hallo! Ich bin Pfeilmacher. Barnabas Pfeilmacher! Freut mich, Euch kennenzulernen!\n\n<Er wischt sich eine Hand an seiner Robe ab, doch als er sie Euch zur Begrüßung reicht ist sie noch immer klebrig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[32190] = { id = 32190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Mogujia", description = "Throm-ka, {class}. Während wir damit beschäftigt waren, unsere Stellung hier zu verteidigen, hat Lordregent Lor'themar Theron eine Forschungsexpedition zum Kun-Lai-Gipfel im Norden geführt.\n\nLeider sieht es so aus, als wäre sie in Schwierigkeiten geraten.\n\nKriegshäuptling Garrosh Höllschrei ist bereits zu Hilfe geeilt, wir brauchen aber weitere Verstärkung.\n\nBrecht nach Norden zum Kun-Lai-Gipfel auf. Sprecht mit Tak-Tak bezüglich einer Transportmöglichkeit.", sourceObjective = "Findet Lordregent Lor'themar Theron bei Mogujia. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", completion = "Seid gegrüßt, {class}. Wir sind eine archäologische Expedition, die diese Ruinen ausgraben soll. Wir hatten keine Ahnung, dass dieses Gebiet von gefährlichen Mogu überlaufen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[32191] = { id = 32191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Wächter", description = "Ehe die Mogu unseren Spähtrupp überwältigten, haben wir Relikte gefunden, die in den Ruinen im Norden verstreut waren.\n\nIch würde gern ein paar Proben davon einsammeln, mit den Terrakotta-Wachhunden der Mogu werden wir aber nicht fertig.\n\nWenn Ihr die Umgebung von ihnen säubern könntet, werden wir unsere Arbeit fortsetzen.", sourceObjective = "Tötet 5 Wächter der Korun.", completion = "Ah! Gut gemacht! Ohne die Wächter sollten wir die Ruinen gefahrlos ausgraben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[32192] = { id = 32192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutlinie", description = "Wir konnten die Wächter der Mogu und ihre Hunde zurückschlagen, etliche Blutelfen aus dem Spähtrupp hatten allerdings nicht so viel Glück.\n\nViele von meinen Leuten sitzen in den Ruinen im Norden fest. Wir arbeiten an einer Lösung, um sie herauszuholen, ich glaube aber, dass es eine unkompliziertere Vorgehensweise gibt.\n\nBegebt Euch zu den Ruinen und tötet alle Wächter, die einen Gefangenen bewachen. Wenn meine Eingebung mich nicht trügt, können wir so unsere Kameraden befreien.", sourceObjective = "Befreit 6 Magier der Herrschaftsoffensive indem Ihr Hüter der Korun tötet.", completion = "Wir Blutelfen haben der Horde treu gedient. In letzter Zeit frage ich mich, welche Vorteile wir aus Garroshs Führung ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32193] = { id = 32193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Mogujia", description = "Die Forscherliga hat vor ein paar Tagen eine Expedition nach Norden entsandt.\n\nWir haben nicht mehr von ihr gehört und ich würde nachts besser schlafen, wenn ich wüsste, dass unsere Leute nicht in Schwierigkeiten stecken.\n\nDen letzten Informationen zufolge war Brann Bronzebart nach Mogujia am Kun-Lai-Gipfel unterwegs.\n\nFindet ihn und erstattet Bericht über ihre Lage. Fennie dort drüben kann Euch hinbringen.", sourceObjective = "Sprecht mit Brann Bronzebart in Mogujia am Kun-Lai-Gipfel. Sprecht mit Fennie Hornsturz in der Löwenlandung für einen Transport.", completion = "Diese Artefakte müssen mehrere tausend Jahre alt sein. Habt Ihr so was schon mal gesehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[32194] = { id = 32194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böses Blut", description = "Die Forscherliga ist hier, um die Ruinen auszugraben, und meine Aufgabe ist es, sie zu beschützen.\n\nAls wir hier ankamen, wimmelte es nur so von Blutelfen. Die Horde scheint genauso großes Interesse an den Mogu zu haben wie wir.\n\nDas ist eine gute Gelegenheit für uns, einige von ihnen aus dem Weg zu schaffen und gleichzeitig ihre Ergebnisse zu stehlen.\n\nTötet die Blutelfen, die Ihr in den Ruinen antrefft, und nehmt ihnen ab, was sie ausgegraben haben.", sourceObjective = "Erlangt 5 Artefakte der Korun von Runensuchern von Silbermond oder von Magiern oder Rittern der Herrschaftsoffensive.", progress = "Worauf sind diese Blutelfen aus?", completion = "Gut gemacht, {class}. Ich wusste, dass Ihr den Auftrag erledigen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[32195] = { id = 32195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgestauter Zorn", description = "Wie es aussieht, wimmelt es hier nur so von verbleibender Sha-Energie.\n\nIhr wisst, was Ihr zu tun habt, {name}. Vernichtet auch die letzten Überbleibsel.", sourceObjective = "Tötet 27 Zornlinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[32197] = { id = 32197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigenartiger Braten", description = "Wir kriegen von überall her Beschwerden, dass die Chefin das ganze gute Essen bekommt und den anderen nur die Reste überlässt.\n\nGanz unter uns, da kann etwas dran sein. Selbst ich bekomme kein so gutes Essen wie sie!\n\nWir brauchen etwas, von dem Sezik eine Menge machen kann, um wenigstens darüber hinwegzutäuschen, wie ungenießbar das Essen hier ist...\n\nIch hab's! Eigenartiger Braten!", sourceObjective = "Besorgt 7 Stücke eigenartiges Fleisch von den wilden Tieren aus der Gegend.", progress = "Was habt Ihr für mich?", completion = "Ich habe Maßstäbe, müsst Ihr wissen! Ich bin Koch, kein Zauberkünstler!\n\nDas richtig Eigenartige hier ist, wie Duke das schaffen will, alle reinzulegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32198] = { id = 32198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abfall ist nicht gleich Abfall", description = "Bevor wir Geschäfte machen, verlangen es die Bedingungen meines Rehabilitationsprogramms, dass ich darüber informiere, dass ich ein ehemaliger Tranksüchtiger bin.\n\nDa ich dies hiermit getan habe, lasst uns über Portale sprechen!\n\nIhr müsst wissen, dass die Portale in den großen Städten - die, die Tag und Nacht aktiv sind - große Mengen magischer Energie an ihre Umgebung abgeben. Diese Energie kristallisiert an den Rändern der Portale und wird allgemein als Abfall betrachtet.\n\nWährend meiner, ähh... Auszeit in der Kanalisation von Dalaran habe ich bemerkt, dass diese Splitter durchaus noch Energie besitzen.\n\nInteresse?", sourceObjective = "Sprecht mit Barnabas Pfeilmacher, um mehr über Portalsplitter herauszufinden.", completion = "Ich wusste es!\n\nHier ist der Haken: in ihrer aktuellen Form sind die Splitter instabil. Doch der Boden in diesem Tal ist berühmt für seine magischen Eigenschaften! Ich bin mir sicher, dass eine interessante Reaktion stattfinden würde, wenn Ihr den Splitter \"einpflanzt\".\n\nEr könnte sich stabilisieren und Ihr hättet ein funktionierendes Portal! Oder... er könnte eine magische Kluft aufreißen, die transdimensionale Schrecken verbreiten würde!\n\nMein Bauchgefühl sagt mir, dass es ein wenig von beidem sein wird, aber es gibt nur einen Weg, das herauszufinden.\n\nHier, nehmt einen Versuchssplitter!", sourceObjectiveStatus = "unverified-source-field" }
quests[32199] = { id = 32199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krasarang-Dampfgericht", description = "Die Chefin wünscht sich Krabben!\n\nWas seht Ihr mich so an? Es ist nicht ungewöhnlich, dass eine feine Person wie ihre Lieblichkeit Krabben zum Abendessen haben will. Was habt Ihr gedacht?\n\nAm Bilgewasserstrand laufen große Krabben herum, die für ihren Feinschmeckergaumen geeignet sein sollten.\n\nBringt Sezik das beste Krabbenfleisch, das Ihr finden könnt!", sourceObjective = "Besorgt 5 Brocken verunreinigtes Zwingzangenfleisch von Zwingzangen am Bilgewasserstrand.", progress = "Die Chefin will also ein Dampfgericht? Vielleicht sollte sie hier herunterkommen und es selbst zubereiten!", completion = "Dieses Fleisch ist ekelhaft. Ich werde jedes einzelne Gewürz brauchen, das ich habe, um den Gestank zu überdecken.\n\nFür die Chefin nur das Feinste!\n\n<Sezik grinst und zwinkert Euch zu.>", sourceObjectiveStatus = "unverified-source-field" }
quests[32200] = { id = 32200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahren von Za'Tual", description = "{name}, ich muss Euch um etwas bitten, das einem Massenmord sehr nahe kommt, aber es muss getan werden.\n\nFindet Trolle in ihrer Stadt oder am Strand und tötet sie, zu unser aller Wohl.", sourceObjective = "Tötet 12 Trolle in Za'Tual.", completion = "Heute wurde viel Blut vergossen. Es klebt an meinen Händen, {name}, nicht an Euren.", sourceObjectiveStatus = "unverified-source-field" }
quests[32201] = { id = 32201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gravierende Umstände", description = "Der Hof der Knochen wimmelt von Truppen der Mogu. Ohne Unterlass führen sie ihre Rituale von Blitz und Donner aus.\n\nWenn wir unseren Auftrag, diese Insel zu erobern, erfüllen sollen, dürfen wir nicht zulassen, dass sie eine so wichtige strategische Position halten.\n\nSie müssen vernichtet werden.", sourceObjective = "Tötet 10 Grabhüter der Shan'ze, Seelenreißer der Shan'ze oder Donnerrufer der Shan'ze.", progress = "Die Mogu sind mächtig, aber mit List und Hartnäckigkeit können wir sie besiegen.", completion = "Exzellent. Ihr habt den Mogu eine Lektion verpasst, die sie nicht so schnell vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32202] = { id = 32202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Trolle" }
quests[32203] = { id = 32203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Mogugeister" }
quests[32204] = { id = 32204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Skumklingen-Bedrohung", description = "Die Ihgalukklamm wimmelt von Saurok. Diese Bestien greifen meine Männer an, breiten ihre Krankheit auf Wild und Wasser in der Nähe aus und stören unsere Arbeit.\n\nDünnt ihre Reihen aus, {name}. Wenn die Horde diese Insel erst unter Kontrolle hat, können wir uns über permanentere Lösungen Gedanken machen.", sourceObjective = "Tötet 10 Saurok der Skumklingen.", completion = "Eines Tages wird diese Insel der Horde gehören. Ich kann nur hoffen, dass sie vorher frei von Saurok sein wird.\n\n<Aethas verzieht das Gesicht.>\n\nWenigstens greifen sie auch die Allianz an.", sourceObjectiveStatus = "unverified-source-field" }
quests[32205] = { id = 32205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt Späherberichte" }
quests[32206] = { id = 32206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es reicht einfach nicht", description = "Die Zandalari hier sind sehr mächtig, {class}. Sie sollten auf keinen Fall unterschätzt werden. Wir können es uns nicht leisten sie zu ignorieren, nur weil sie keine Schwerter schwingen.\n\nEs treffen jeden Tag mehr ein und mit ihnen Jahrhunderte magischen Wissens. Wir müssen uns um diese Bedrohung kümmern, und zwar schnell.\n\nHelft uns dabei, dieses Gebiet zu befrieden, {class}. Vielleicht können wir währenddessen ja sogar etwas von ihnen lernen.", sourceObjective = "Tötet 8 Zandalaritrolle jeglicher Art auf der Terrasse des Eroberers.", completion = "Beeindruckend, wie leicht Ihr sie bezwingen konntet.\n\nVielleicht seid Ihr es, den sie nicht unterschätzen sollten. Vielen Dank für Eure Unterstützung, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32207] = { id = 32207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verechst und zugenäht", description = "In den Bestienpferchen werdet Ihr einige der besten Wildtierzähmer des Zandalarimilitärs finden. Sie sind darauf trainiert, mit Axt, Tier und Klauen zu töten. Dort bilden sie ihre Reiterschaft aus.\n\nIhr müsst für uns alle Zandalari töten, die Ihr in den Bestienpferchen findet, bevor sie ihre berittenen Monstrositäten hinaus aufs Schlachtfeld schicken können.", sourceObjective = "Bezwingt 10 Trolle der Zandalari in den Bestienpferchen.", completion = "Ein einziger geschulter Bestienrufer der Zandalari kann auf dem Schlachtfeld mit seinem wilden Reittier gut zwanzig Mann töten. Euer Präventivschlag hat viele Leben gerettet. Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[32208] = { id = 32208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Maximalkondensator", description = "In den Minen nördlich von hier wird Geistereisenerz abgebaut und mit Blitzenergie energetisiert.\n\nWir müssen die Bohrer zerstören, mit denen sie das Erz fördern. Normalen Angriffen gegenüber sind sie unempfindlich, jedoch könnten sie mit den richtigen Methoden überladen werden.\n\nOh – und wenn Ihr schon dabei seid, tötet doch auch denjenigen, der die Operation beaufsichtigt.", sourceObjective = "Macht Euch an den drei Blitzbohrern in den Blitzaderminen zu schaffen, um sie zu zerstören, und tötet Metallfürst Mono-Han.", sourceObjectiveStatus = "unverified-source-field" }
quests[32209] = { id = 32209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet unsere Späher!", sourceObjective = "Rettet die drei gefangenen Agenten der Sonnenhäscher aus der Blitzadermine und tötet Metallfürst Mono-Han.", sourceObjectiveStatus = "unverified-source-field" }
quests[32210] = { id = 32210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moguboss für Schlüssel töten, Objekt hinter Sprungpuzzle benutzen" }
quests[32211] = { id = 32211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nalak der Sturmfürst", description = "Tötet Nalak" }
quests[32212] = { id = 32212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Angriff auf Zeb'tula", description = "Unsere Erkundungstätigkeiten an der Küste haben uns wertvolle Informationen über die Insel eingebracht, {class}.\n\nWir werden allerdings nichts erreichen, wenn wir nicht weiter auf das Festland vordringen.\n\nIch möchte, dass Ihr Euch diesem Angriff anschließt. Ein Champion wie Ihr könnte die Schlacht im kritischen Moment zu unseren Gunsten wenden.\n\nWenn Ihr bereit seid, mit dem Angriff zu beginnen, sprecht mit mir.", sourceObjective = "Schließt den Angriff auf Zeb'tula ab. Sprecht mit Lor'themar Theron, um den Angriff zu beginnen.", completion = "Ja! Ihr habt es geschafft, Champion!\n\nWir werden sein wie eine Flut, die über diese Insel hinwegbraust und unserem Volk eine neue Bestimmung bringt. Und Ihr, Held, seid an vorderster Front.", sourceObjectiveStatus = "unverified-source-field" }
quests[32213] = { id = 32213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Feinde", description = "Jaina und die Kirin Tor denken also, dass sie uns einfach wieder von hier vertreiben können? Ich werde nicht untätig mit ansehen, wie sie ihre Vergehen aus Dalaran wiederholen!\n\nDieses Mal leisten wir Gegenwehr! Dieses Mal werden wir diejenigen sein, die Druck ausüben.\n\nBegebt Euch zur Violetten Erhebung und bezwingt jeden Agenten der Kirin Tor, den Ihr finden könnt.", sourceObjective = "Tötet auf der Insel des Donners 10 Einheiten oder Spielercharaktere, die für die Kirin Tor arbeiten.", completion = "Die Violette Erhebung hat heute also eine deutliche Rotfärbung? Gut gemacht, {name}.\n\nDieser Kampf wird noch eine Weile andauern, fürchte ich. Wir dürfen keine Schwäche zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32214] = { id = 32214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilgewässer Spitzel", description = "Es gibt nichts Nervenaufreibenderes, als dahinzuwandern, sich um seine eigenen Angelegenheiten zu kümmern und festzustellen, dass man verfolgt wird. Ich schwör's, ich höre es überall hier unten! Wir werden beobachtet!\n\nIch habe das Gefühl, der ganze Strand ist voller Spione!\n\nIch habe ein paar Verbesserungen an unseren Infrarotbrillen vorgenommen, um der Sabotage ein Ende zu bereiten! Jetzt müsst Ihr sie nur noch für mich ausprobieren! Entledigt Euch ruhig sämtlicher Spione, die Ihr stellt.", sourceObjective = "Tötet 10 Saboteure des SI:7 an der Herrschaftsfeste und am Bilgewasserstrand.", completion = "Sehr schön, {name}! Ich wusste es! Ich wusste doch, dass die Allianz dort unten herumschleicht!\n\nKeiner macht an einem Bilgewässer-Bohrturm herum und kommt ungeschoren davon!", sourceObjectiveStatus = "unverified-source-field" }
quests[32215] = { id = 32215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abscheuliche Opfer", description = "Die Zandalari richten ihre schändlichen Riten gegen unsere Leute! Sie müssen aufgehalten werden!\n\nDringt in das Herz von Za'Tual vor und zerstört ihre Altäre.", sourceObjective = "Zerstört die Opferaltäre der Zandalari.", completion = "Ich konnte sogar hier spüren, wie die Magie ihrer Altäre sich verflüchtigt hat, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32216] = { id = 32216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreischen vor Qualen", description = "Die Zandalari behandeln ihre Himmelskreischer kaum besser als krabbelndes Ungeziefer. Sie unterwerfen sie mit Gewalt und Quälerei ihrem Willen.\n\nIch kann hören, wie sich einer von ihnen unter ihrer Behandlung vor Qualen windet.\n\nFindet den gepeinigten Himmelskreischer in Za'Tual und helft ihm, sich von seinen Fängern zu befreien.", sourceObjective = "Befreit den gepeinigten Himmelskreischer.", completion = "Er hat was?! Seinen Meister getötet? Wunderbar. Diese Himmelskreischer geben sich nicht so leicht geschlagen, wie ich dachte. Danke, dass Ihr geholfen habt, das Tier zu befreien, {race} – so ist es eine Bedrohung weniger für die Horde, und eine mehr für die Zandalari.", sourceObjectiveStatus = "unverified-source-field" }
quests[32217] = { id = 32217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Opfergaben", description = "Die Geisterbinder der Zandalari führen Opferriten aus, die die Loa und ihre abstoßenden Götter besänftigen sollen. Diese finsteren Rituale beinhalten die Opferung unserer Leute.\n\nZerstört alle Opfergaben, die Ihr bei ihren Zelten in Za'Tual finden könnt, und vielleicht können wir die Opfer stoppen.", sourceObjective = "Zerstört 6 Zandalariopfergaben.", progress = "Ich hoffe wirklich, dass sie das verlangsamt. Die Opfer schreiten mit beängstigendem Tempo voran.", completion = "Die Welle blutiger Rituale ist eingedämmt, wenigstens für eine Weile. Danke für Eure Bemühungen, die Opfer aufzuhalten, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32218] = { id = 32218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche des Feindes", description = "Die Mogu hier im Hof der Knochen stocken ihre Armee auf, indem sie die Geister ihrer Gefallenen erwecken.\n\nWir dürfen nicht zulassen, dass sie ihre gefallenen Krieger wiederbeleben.\n\nNehmt diese Fackel und verbrennt alle mumifizierten Leichen, die Ihr finden könnt.\n\nWir werden unsere Feinde vernichten, bevor sie die Gelegenheit haben, aufzuerstehen.", sourceObjective = "Verbrennt 8 mumifizierte Überreste.", completion = "Dank Euch werden die Toten nicht mehr auferstehen, {name}. Exzellente Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32219] = { id = 32219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marmor, Stein und Qilen bricht", description = "Unser Angriff auf den Hof der Knochen schreitet voran. Unsere Fortschritte sind weiterhin langsam, aber messbar.\n\nLeider haben wir mehrere Berichte über steinerne Qilenstatuen erhalten, die ohne Vorwarnung zum Leben erwachen. Ich kann nicht zulassen, dass diese Qilen meine Forschungsexpedition bedrohen.\n\nBegebt Euch in den Hof der Knochen und zerstört alle Qilenstatuen, die Ihr finden könnt.", sourceObjective = "Zerstört 8 Grabwächter.", completion = "Ich freue mich zu hören, dass Ihr die Qilen in tausend winzige Stücke zerschlagen habt. Ihr habt viel zu unseren Kriegsanstrengungen beigetragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32220] = { id = 32220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenrettung", description = "Wir bekämpfen die Mogu im Hof der Knochen, aber ich fürchte, dass wir ihnen nur Material für ihre abscheulichen Rituale liefern.\n\nDie Mogu töten ihre Gefangenen nicht einfach – sie stehlen ihre Seelen und hauchen sie Gerätschaften aus Stein ein oder formen die Gefallenen zu geisterhaften Kriegsmaschinen um.\n\nHorde oder Allianz, es macht keinen Unterschied. Wir können den Mogu nicht erlauben ihre Reihen wieder aufzustocken.\n\nGeht zur Grabstätte. Befreit die Gefangenen, die noch leben.", sourceObjective = "Rettet 6 Späher der Sonnenhäscher oder des Silberbunds.", completion = "Danke, {name}. Ihr habt mein Herz durch Eure heldenhaften Taten von einer schweren Last befreit. \n\nIch werde Eure heutigen Anstrengungen in Erinnerung behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[32221] = { id = 32221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstürmung des Strandes", description = "Unsere Holzvorräte sind durch ständige Angriffe aus der Löwenlandung gefährdet.\n\nBisher konnten wir die Angreifer in Schach halten, es wird aber Zeit, dass wir die Muskeln spielen lassen!\n\nBrecht zur Küste auf und spaltet ein paar Schädel!", sourceObjective = "Tötet 10 beliebige Angreifer der 7. Legion.", completion = "Ausgezeichnete Arbeit dort unten, {name}! Das sollte sie uns eine Zeit lang vom Leib halten!", sourceObjectiveStatus = "unverified-source-field" }
quests[32222] = { id = 32222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Chefingenieur Getriebeschlüssel", description = "Wegen Verbrechen gegen den Betrieb in Bilgewasser gesucht!\n\nChefingenieur Getriebeschlüssel wurde zuletzt bei der Errichtung eines riesigen Spinnenpanzers am Rand des Bilgewasserstrands gesehen.\n\nMan sollte sich ihm nur mit größter Vorsicht nähern.\n\nFür Getriebeschlüssels Vernichtung ist eine hohe Belohnung ausgesetzt.", sourceObjective = "Vernichtet Chefingenieur Getriebeschlüssel am Rand des Bilgewasserstrandes.", completion = "Ausgezeichnete Arbeit, {class}! Das bringt uns einen Schritt näher an ihre Vertreibung aus Pandaria!", sourceObjectiveStatus = "unverified-source-field" }
quests[32223] = { id = 32223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Leutnant Ethan Jacobson", description = "Wegen Verbrechen an den Truppen der Herrschaftsfeste gesucht!\n\nLeutnant Ethan Jacobson ist für die Ausführung mehrerer Bodenangriffe gegen den Bilgewässer Holzbetrieb verantwortlich.\n\nEr wurde zuletzt auf einer Insel im Süden von Blitzbeils Holzhof gesichtet.", sourceObjective = "Tötet Leutnant Ethan Jacobson auf den Südlichen Inseln im Süden von Blitzbeils Holzhof.", completion = "Jeder Tag, an dem ein weiterer Anführer der Löwenlandung fällt, ist ein guter Tag, {class}! Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[32224] = { id = 32224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch nie wieder!", description = "Habt Ihr die Geister gesehen, die im Friedhof umherwandern?\n\nDas sind auferstandene Urahnen, die in diese Welt zurückgerufen wurden.\n\nWerden sie verärgert, greifen sie schnell und lautlos an, und es werden von Tag zu Tag mehr.\n\nSie gehören nicht hierher. Vernichtet sie und schickt sie zurück in das Totenreich.", sourceObjective = "Tötet 15 auferstandene Urahnen.", completion = "Wunderbare Arbeit, {class}. Das wird unserer Offensive sehr helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32225] = { id = 32225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Donners", description = "Auf dem Friedhof, in den tiefsten Ruinen der westlichen Krypta, laden die mächtigsten Zauberer des Donnerkönigs einen Blitzableiter mit knisternder Elektrizität auf.\n\nWir vermuten, dass mit dieser Waffe unsere Festung am Morgensucherkap zerstört werden soll.\n\nWir dürfen keine Zeit verlieren. Ihr müsst das Ritual sofort stoppen.", sourceObjective = "Unterbrecht das Ritual der Donnerrufer der Shan'ze.", completion = "Ihr übertrefft meine Erwartungen immer wieder, {class}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32226] = { id = 32226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Krypta", description = "Die Archäologische Akademie verdient sich da draußen eine goldene Nase, fast wörtlich!\n\nJeden Tag finden die Forscher mehr und mehr Relikte, die untersucht und katalogisiert werden müssen.\n\nVor Kurzem hat einer unserer Abenteurer diese Schriftrolle im Hof der Knochen gefunden.\n\nIch glaube, dass mit dieser Zauberformel bis in die Totenwelt gerufen werden kann. Und wenn meine Mogukenntnisse mich nicht täuschen, würde ich sagen, dass man sie im letzten Raum der Halle der Ehrwürdigen benutzen soll.\n\nWärt Ihr bereit, meine Theorie zu testen?", sourceObjective = "Benutzt die Zauberformel von Gura in der Halle der Ehrwürdigen und besiegt dann Gura den Zurückgeforderten.", completion = "Oh ja, Ihr habt soeben meine Theorie bestätigt! Danke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32227] = { id = 32227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer zukünftigen Bedrohung vorbeugen", description = "Die Kreaturen, auf denen die Zandalari reiten, sind nicht von Anfang an so groß. Ebensowenig sind sie sofort die bösartigen und treuen Kreaturen, zu denen sie werden.\n\nWenn Ihr einige der Himmelskreischerjungtiere vom Strand verscheuchen könnt, haben Sie vielleicht eine Chance auf ein wahres Leben.", sourceObjective = "Erschreckt 12 Himmelskreischerjungtiere, indem Ihr in ihre Nähe lauft.", progress = "Konntet Ihr die Himmelskreischerjungtiere verscheuchen?", completion = "Ihr seid zurück, {race}. Ich hoffe, diese jungen Himmelskreischer bekommen das Leben, das ihnen gebührt, ohne die brutale Behandlung durch die Trolle erleiden zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32228] = { id = 32228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schaudernde Moor", description = "Im Sumpf lebt eine riesige Bestie. Sie hat uns noch nicht angegriffen, aber ich würde nicht darauf wetten, dass dies auch so bleibt.\n\nTötet sie, bevor sie der Hunger dazu antreibt, unsere Verteidigungsstellungen anzugreifen.", sourceObjective = "Tötet den mächtigen Teufelssaurier.", completion = "Mit Euch sollte man es sich nicht verscherzen. Ich bin sicher, dass ich in Zukunft Verwendung für Euch haben werde.\n\nKommt morgen zu mir zurück, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32229] = { id = 32229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marodierenden Trollkampftrupp töten" }
quests[32230] = { id = 32230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koloss der Zandalari", description = "Die Trolle haben eines ihrer riesigen Konstrukte an die südliche Straße geschickt, sodass es uns den Weg über die Insel blockiert. Sorgt dafür, dass die Straße geräumt wird, {class}.", sourceObjective = "Zerstört den Koloss der Zandalari.", completion = "Wenn ich Euch eine Aufgabe gebe, wird sie erledigt.\n\nGut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32231] = { id = 32231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lichtspur im Dunkel", description = "Im Düstermoor gibt es eine Art finstere Magie, die selbst unsere magische Beleuchtung auslöscht, und so fällt es unseren Spähern schwer, den Weg zu finden.\n\nWenn Ihr durch den Sumpf reist, entzündet bitte alle Fackeln die Ihr findet, sodass unsere Männer sich orientieren können. Vielleicht findet auch Ihr so Euren Weg zurück.", sourceObjective = "Entzündet 8 Fackeln im Düstermoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[32232] = { id = 32232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Größe zählt doch", description = "Während meines letzten Spähzugs habe ich etwas Seltsames bemerkt. Eine Gruppe Zandalari führt ein Ritual durch, dessen Ziel ein sehr großer Wächter zu sein scheint. Möglicherweise versuchen sie, ihn zu reanimieren.\n\nWir müssen dieses Ritual unterbrechen und den Wächter zerstören. Etwas von dieser Größe kann nicht gut für uns sein.\n\nIch habe eine Späherin vorgeschickt, um sie zu beobachten. Trefft Euch mit ihr und findet heraus, wie man sie aufhalten kann.", sourceObjective = "Zerstört Wächter Tak'u auf der Terrasse des Eroberers.", completion = "Dann war es also richtig von mir, besorgt zu sein. Es war gut, dass Ihr einschreiten konntet, bevor der Wächter vollständig aufgeladen war.\n\nGute Arbeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32233] = { id = 32233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwaffnender Charme", description = "Seht Euch um, {class}. Was seht Ihr? Ich sehe eine Gelegenheit.\n\nDie Zauberwirker hier erfüllen die Waffen der Zandalari mit mächtiger Magie. Als ob eine scharfe Klinge allein nicht genug wäre, um selbst den stärksten Gegner einen Kopf kürzer zu machen.\n\nWährend meiner Spähzüge habe ich bemerkt, dass diese Waffen nicht sonderlich gut bewacht werden. Und da kommt Ihr ins Spiel...\n\nWenn wir einige der Waffen stehlen, könnten sie uns vielleicht nützlich sein. Zumindest befinden sie sich dann nicht mehr in den Händen unserer Feinde.", sourceObjective = "Stehlt 7 loabeseelte Klingen von der Terrasse des Eroberers.", progress = "Also? Was habt Ihr gefunden?", completion = "Exzellente Arbeit, {class}!\n\nDiese Waffen allein sind schon erschreckend, ganz zu schweigen von der Magie, die auf ihnen liegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32234] = { id = 32234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen ist Macht", description = "Die Zandalari hier üben eine andere Art der Magie aus. Wir müssen sie zunächst verstehen, bevor wir sie bezwingen können, {class}.\n\nIhre Kontrolle über das Arkane und den Schatten ist beeindruckend. Ich möchte erfahren, wie sie dort so erfolgreich sind, wo so viele vor ihnen versagten.\n\nIch glaube, ihre Ritualartefakte können die Antworten geben, die ich suche. Bringt mir eine Anzahl der von Euch gefundenen Artefakte und ich werde sicherstellen, dass Ihr gebührend entlohnt werdet.", sourceObjective = "Sammelt in der Gegend um die Terrasse des Eroberers 6 Ritualartefakte ein.", progress = "Habt Ihr die Artefakte gefunden?", completion = "Die werden ihren Zweck voll und ganz erfüllen, {class}. Exzellente Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32235] = { id = 32235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosiver Cocktail!", description = "Die Gnome haben ihre Fluggeräte mitgebracht. Ich will, dass mein Himmel FREI bleibt!\n\nEgal, welches Reittier Ihr bei Euch habt – hinauf mit Euch und zerstört diese erbärmlichen Geräte.\n\nIhr könnt diesen Grog verwenden, den ich von einem unserer Goblinverbündeten \"besorgt\" habe. Ihr wärt besser damit bedient, mit ihm Gyrokopter aus der Luft zu holen, als ihn in den Gurgeln dieser kleinen grünen Unholde versickern zu lassen.", sourceObjective = "Verwendet den Bilgewässer Molotowcocktail, um 6 Gyrokopter X2 der Himmelsfeuer zu zerstören.", completion = "Ha! Primitive mechanische Spielzeuge können es mit einer gezielt geworfenen Flasche Grog nicht aufnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32236] = { id = 32236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kratz-Ab!", description = "In dieser Höhle wimmelt's nur so von fiesen Schieferspinnen! Wie soll man denn seine Arbeit erledigen, wenn sie die Minenarbeiter UND das Erz auffressen?!\n\nDas wäre eine gute Gelegenheit, meine neue Erfindung einzusetzen: Kratz-Ab! Man muss einfach nur die Schieferspinnen mit diesem Zeug einsprühen. Das mögen die gar nicht, und für die Minenarbeiter scheint es kaum längerfristige Nebenwirkungen zu haben!\n\nWas kann da schon schiefgehen?\n\nNehmt diesen praktischen Sprüher mit und macht Euch an die Arbeit.", sourceObjective = "Sprüht 5 Aufgebrachte Schieferspinnen mit dem \"Kratz-Ab\"-Spray ein und beseitigt 12 Schiefersplitter.", completion = "Na das hört man gerne! Ich wette, diese Spinnen werden es sich jetzt zweimal überlegen, bevor sie sich wieder in eine Bilgewasseroperation einmischen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32237] = { id = 32237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kostbare Ressource", description = "Wir haben hier wirklich zu viel des Guten, {name}!\n\nUnser Bohrturm weiß nicht mehr, wohin mit all dem Öl, das wir aus dem Boden fördern. Er platzt sprichwörtlich aus allen Nähten! Um genauer zu sein, er platzt aus den Ventilen.\n\nIch arbeite schon Tag und Nacht, um die Ventile zu reparieren, aber immer, wenn ich endlich alle geflickt habe, sind sie gleich wieder kaputt.\n\nEs kommt mir vor, als würde mir jemand folgen... Aber was für ein lächerlicher Gedanke...\n\nVielleicht habt Ihr ja mehr Glück. Versucht, so viele der Ventile abzudichten, wie Ihr könnt.", sourceObjective = "Dichtet 8 defekte Ventile in und um Radflutschs Ölspritzer ab.", completion = "Man ist mir also wirklich gefolgt! Diese dreckigen Schleicher!\n\nIch sollte wohl ein paar hübsche Überraschungen für diese Feiglinge auslegen. Überraschungen, die sie so richtig umhauen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[32238] = { id = 32238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Universalfernsteuerungsexplosion", description = "Die Mecha-Stampfer machen uns hier wirklich das Leben schwer, doch ich glaube, ich habe die Lösung!\n\nIch habe mir diese Universalfernsteuerung gebaut, aber scheinbar arbeitet sie auf einer bestimmten Frequenz, die eine nützliche Wirkung hat!\n\nEs scheint ganz so, als schwäche diese Frequenz ihre Rüstung!\n\nBenutzt die Fernsteuerung, um sie von ihrem hohen Ross zu holen und ihnen dann die Visage zu polieren!", sourceObjective = "Zerstört 9 Mecha-Stampfer des Schildwalls in und um Blitzbeils Holzhof.", completion = "Gute Arbeit, {name}! Ich konnte das Feuerwerk von hier aus sehen!\n\nWer hätte gedacht, dass genial zu sein so einfach ist? Ich muss mich noch nicht einmal mehr anstrengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32242] = { id = 32242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergrabene Geheimnisse", description = "Ich habe gehört, dass die Mogu einst Hunderte verborgener Waffenkammern voller erderschütternder Waffen ihr Eigen nannten.\n\nWenn sich eine Moguarmee für den Krieg rüstete, erfüllte sie die Herzen ihrer Feinde mit Furcht und Schrecken.\n\nDas ist GENAU die Art Wissen, die ich hier in Pandaria suche!\n\nIch habe eine Expedition entsandt, um ein paar Ruinen im Westen zu erforschen, aber ihre Arbeitsmoral ist die schwachsinniger Peons!\n\nGeht hin und sprecht mit Fanlyr Silberdorn, ihrem Anführer. Sagt ihm, dass ich Resultate sehen will, und zwar sofort.", sourceObjective = "Sprecht mit Fanlyr Silberdorn bei der Ahnenhöhe im Tal der Ewigen Blüten.", completion = "Der Kriegshäuptling schickt Euch? Was hat er zu sagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[32243] = { id = 32243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Machtquelle der Korun", description = "Nah halli-hallo! Habt Ihr schon mal so was geseh'n wie die alten Statuen hier? Faszinierend!\n\nAls ich vorhin die Ruinen da oben ausgekundschaftet hab', ist mir auf dem höchsten Punkt oben was Interessantes aufgefall'n.\n\nIch kam nicht nah genug ran, aber ich glaub', es könnte eine von diesen Mogustatuen sein... außer, dass sie sich bewegt hat!\n\nIch schaff's nicht durch diese ganzen fiesen Blutelf'n, aber Ihr seht aus, als hättet Ihr das Zeug dazu.\n\nWürd' es Euch was ausmachen, da hochzuklettern und mir zu bringen, was immer von Interesse sein könnte?", sourceObjective = "Nehmt dem Spruchwirker der Korun eine Sha-berührte Klaue ab.", progress = "Habt Ihr da oben was gefunden?", completion = "Oha, was ist das denn?", sourceObjectiveStatus = "unverified-source-field" }
quests[32244] = { id = 32244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Korun", description = "Diese Terrakottawächter sind beängstigend, aber nicht annähernd so furchterregend wie die Geschöpfe, die uns ganz oben in den Ruinen begegnet sind.\n\nEinige Überlebende unter unseren Spähern wollen eine Art Spruchwirker der Mogu auf der höchsten Erhebung im Norden gesehen haben.\n\nEr praktiziert eine Magie, wie wir sie noch nie erlebt haben.\n\nWir müssen möglichst viel über diese Kreatur erfahren. Tötet ihn und bringt mir alles, was Ihr findet.", sourceObjective = "Nehmt dem Spruchwirker der Korun einen Korunkodex ab.", progress = "Was habt Ihr herausgefunden?", completion = "Wirklich bemerkenswert! Das ist genau die Art Artefakt, die wir hier finden wollten!", sourceObjectiveStatus = "unverified-source-field" }
quests[32246] = { id = 32246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit der Späherin", description = "Es ist zwei Monate her, seitdem sich die Nebel gelichtet haben. Späher der Allianz, die nach einem geeigneten Ankerplatz für ihre Flotte suchen, haben die Streitmächte der Horde an einem Strand in der Krasarangwildnis in ein Gefecht verwickelt.\n\nTrefft Euch mit Späherin Lynna, um bei der Eroberung des Landeplatzes zu helfen.", sourceObjective = "Sprecht mit Späherin Lynna in der Krasarangbucht in der Krasarangwildnis.", completion = "Ihr kommt gerade rechtzeitig, {class}. König Wrynn wird gleich hier sein, und die volle Kampfkraft unserer Flotte wird schon bald folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32247] = { id = 32247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein König unter den Menschen", description = "Es ist höchste Zeit, wir müssen Trottmann finden und den Strand sichern.\n\nAußerdem sollten wir nach den Zwergen sehen: Die Forscherliga ist zäh, ihre Mitglieder sind aber keine Soldaten. Sie sollten sich an der Klippe nördlich von hier aufhalten.\n\nReiten wir los, {class}. Für unsere Freunde. Für die Allianz.", sourceObjective = "Tötet 25 Mitglieder der Horde und begleitet König Varian Wrynn, um Marschall Trottmann und Hilda Hornsturz zu finden.", progress = "Die Allianz wird der Schild sein, der Pandaria vor der Horde schützt.", completion = "Ich bin zufrieden mit dieser Stelle. Zeit, die Flotte an Land kommen zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32248] = { id = 32248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein wenig Geduld", description = "König Varian braucht entschlusskräftige Abenteurer, um ihm beim Entscheidungskampf zwischen Tyrande Wisperwind und einer Einheit Hordenkrieger, die sich im Tempel des Roten Kranichs verschanzt haben, zu helfen.\n\nMeldet Euch unverzüglich bei ihm!", sourceObjective = "Betretet das Szenario Ein wenig Geduld und meldet Euch bei König Varian Wrynn.", completion = "Schön, Euch wiederzusehen, {name}.\n\nWir haben es hier mit einer heiklen Situation zu tun. Wir müssen unsere nächsten Schritte vorsichtig planen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32249] = { id = 32249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit der Späherin", description = "Es ist zwei Monate her, seitdem sich die Nebel gelichtet haben. Späher der Horde, die nach einem geeigneten Ankerplatz für ihre Flotte suchen, haben die Streitmächte der Allianz auf einer kleinen Insel vor der Küste der Krasarangwildnis in ein Gefecht verwickelt.\n\nTrefft Euch mit Späherin Rokla, um bei der Eroberung des Landeplatzes zu helfen.", sourceObjective = "Sprecht mit Späherin Rokla bei der Landezone der Horde in der Krasarangwildnis.", completion = "Ihr kommt gerade rechtzeitig. Der Kriegshäuptling wird gleich eintreffen. Wenn dieser Ort seiner Inspektion standhält, wird die Flotte folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32250] = { id = 32250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Kriegshäuptlings", description = "Kommt, {class}! Ich möchte diese Insel erkunden und sicherstellen, dass mein Landungstrupp seine Arbeit gemacht hat.\n\nBlutwache Gro'tash sollte irgendwo auf der Nordseite der Insel nach einem geeigneten Ort zur Errichtung unserer Festung suchen. Das Untersuchungsteam der Goblins wird auf der Suche nach Öl zur Ostküste gegangen sein.\n\nMachen wir diesem lächerlichen Schauspiel ein Ende - dieses Land soll der Horde gehören!", sourceObjective = "Begleitet Garrosh Höllschrei, sucht Blutwache Gro'tash und Grizzle Radflutsch und tötet 25 Mitglieder der Allianz.", progress = "Blutschrei dürstet nach dem Blut der Allianz.", completion = "Gute Arbeit. Niemand kann unsere Präsenz hier verhindern!", sourceObjectiveStatus = "unverified-source-field" }
quests[32251] = { id = 32251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Dolch im Dunkel", description = "Schattenjäger Vol'jin hat sich einer Spähergruppe der Kor'kron bei einer wichtigen Mission für den Kriegshäuptling angeschlossen.\n\nEin stolzes Mitglied der Horde wie Ihr kann natürlich gern mitkommen, seid aber gewarnt - es könnte unangenehm werden.", sourceObjective = "Betretet das Szenario Ein Dolch im Dunkel und meldet Euch bei Vol'jin.", completion = "Schön, dich zu seh'n, Mann. Für diese Mission brauch ich echte Verbündete an meiner Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[32252] = { id = 32252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorboten der Loa", description = "Habt Ihr von den Loa gehört? Wir verstehen nicht vollständig, worum es sich bei ihnen handelt, aber es scheint sich um eine Art dunkle Magie mit einem gewissen Bewusstsein zu handeln.\n\nWir wissen nicht, über was für Mächte diese Loa verfügen, aber ich muss Euch bitten, ihre Rituale aufzuhalten, {class}.", sourceObjective = "Tötet 2 Vorboten der Loa.", completion = "Ich kann mir nur vorstellen, welcher Schrecken Zeuge Ihr geworden seid, {name}. Eure Tapferkeit wurde heute auf die Probe gestellt, und Ihr habt die Horde in der Erfüllung Eurer Pflicht nicht enttäuscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[32253] = { id = 32253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ENTFERNEN (Nicht mehr benutzt)" }
quests[32254] = { id = 32254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saurok manipulieren", description = "Ich habe drei Magister in die Ihgalukklamm geschickt, um die Saurok zu überwachen und sie – wenn möglich – gegen die Mogu aufzuwiegeln. Ihr müsst sie für mich finden und herausfinden, ob sie Versorgung oder Hilfe benötigen.\n\nSie sind wahrscheinlich versteckt. Haltet nach schimmernden Lichtsäulen im Dorf der Saurok Ausschau.", sourceObjective = "Meldet Euch bei Magister Arlan, Magister Sarien und Magistrix Vesara.", completion = "<Der Erzmagier hört Eurem Bericht aufmerksam zu.>\n\nIch verstehe. Danke für Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32255] = { id = 32255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekonstruktion", description = "Die Saurok testen unaufhörlich unsere Grenzen aus, und normalerweise können unsere Konstrukte sie zurückschlagen. Einige Konstrukte wurden jedoch besiegt und zurück in die Ihgalukklamm geschleppt.\n\nIch will diese Konstrukte zurück. Keine schleimige Echse wird das Eigentum der Sonnenhäscher stehlen, während ich hier das Sagen habe.", sourceObjective = "Beschafft die vier gestohlenen Konstrukte der Sonnenhäscher wieder.", completion = "Schon besser.\n\nDanke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32256] = { id = 32256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg eines Reichs", description = "Kriegshäuptling Garrosh Höllschrei ist mit einem Trupp seiner besten Elitesoldaten gen Norden ausgeschwärmt.\n\nErstattet ihm von unserer Siegesserie im Kampf gegen die Allianz Bericht.\n\nSprecht mit Tak-Tak bezüglich einer Transportmöglichkeit.", sourceObjective = "Findet Kriegshäuptling Höllschrei beim Schrein der Zwei Monde. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", completion = "Was gibt es zu berichten?", sourceObjectiveStatus = "unverified-source-field" }
quests[32257] = { id = 32257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stimme der Götter", description = "Zu langsam!? Wir arbeiten für den Kriegshäuptling, so schnell wir nur können!\n\nWir müssen vorsichtig bei den Ausgrabungen vorgehen, jeden Fund einzeln katalogisieren und natürlich auch die Sicherheitsvorschriften befolgen. Das muss er schon verstehen!\n\nNun, möglicherweise haben wir ihm schon bald etwas zu zeigen. Seht Ihr diese Steinstatue im Westen?\n\nWir vermuten, dass es sich bei ihr um ein antikes Steinspeicherbehältnis handelt. Jetzt müssen wir nur noch einen Weg finden, es zu öffnen.\n\nWenn Ihr uns bei unseren Ausgrabungen helfen möchtet, geht bitte vorsichtig vor.", sourceObjective = "Untersucht den Quecksilberwächter und besorgt die uralte Tafel der Korun.", progress = "Wir sind durchaus in der Lage, mit diesen Ausgrabungen fertigzuwerden. Ich weiß, der Kriegshäuptling schickt Euch, aber wenn er schnell Resultate sehen will, sollte er uns unsere Arbeit machen lassen.", completion = "Hmm... sehr interessant. Diese Tafel dürfte so manches Geheimnis bergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32258] = { id = 32258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordenquestwahl: PvP" }
quests[32259] = { id = 32259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordenquestwahl: PvE" }
quests[32260] = { id = 32260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzquestwahl: PvE" }
quests[32261] = { id = 32261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzquestwahl: PvP" }
quests[32262] = { id = 32262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefesseltes Publikum", description = "Die Kirin Tor sind zu weit gegangen! Jetzt haben sie einige Sonnenhäscher gefangen genommen!\n\nVerhandlungen über einen Austausch kommen nicht in Frage. Wir kümmern uns selbst darum.\n\nGeht zur Violetten Erhebung und befreit so viele Gefangene wie Ihr nur könnt. Lasst Euch nicht selbst gefangennehmen. Wir können es uns nicht leisten, auch noch Euch zu verlieren.", sourceObjective = "Befreit 5 gefangene Sonnenhäscher auf der Violetten Erhebung.", completion = "Diejenigen, die Ihr heute gerettet habt, würden Euch sicher danken, wenn sie die Kraft dazu hätten.\n\nUnsere Arbeit hier ist nicht getan. Ich weigere mich, irgendjemanden zurückzulassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32263] = { id = 32263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späher in der Nähe des feindlichen Lagers finden (verletzt, zurückteleportieren)" }
quests[32264] = { id = 32264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezaubernd", description = "Jaina besitzt mehrere mächtige magische Artefakte. Auch auf Reisen sind diese Gegenstände immer bei ihr und nie außer ihrer Reichweite. Ich interessiere mich für einen dieser Gegenstände.\n\nEin Buch, mit Wissen gefüllt, das von einem Erzmagier an den nächsten weitergegeben wird. Ich habe bis jetzt nur Blicke darauf erhaschen können.\n\nJetzt da wir auf verfeindeten Seiten stehen sehe ich keinen Grund, ihr das Buch nicht zu entwenden.", sourceObjective = "Beschafft Euch Jainas verwittertes Zauberbuch von der Violetten Erhebung.", progress = "Habt Ihr es? Habt Ihr das Buch?!", completion = "Dieses Buch habe ich schon seit Jahren gewollt, {race}. Seine Macht ist unmöglich in Worte zu fassen. Ihr habt mir einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32265] = { id = 32265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgeladenes Moganit", description = "Wir haben jeden Tag Spione in die Basis der Kirin Tor geschickt. Einige davon mit dem Befehl, dem Feind aufgeladenes Moganit zu entwenden und es hierher zu bringen.\n\nSie sind nicht zurückgekehrt, obwohl ich belegen kann, dass sie die Basis der Kirin Tor verlassen haben.\n\nDurchkämmt den Dschungel zwischen hier und dort und findet alles aufgeladene Moganit, das vielleicht unterwegs verloren gegangen ist. Bringt es zu mir, und wir werden es zu verwenden wissen.", sourceObjective = "Beschafft ein Stück aufgeladenes Moganit und bringt es zu Hocharkanist Savor.", completion = "Gut gemacht, Champion. Dieses Artefakt wird in unseren Händen besser aufgehoben sein als in denen der Kirin Tor.", sourceObjectiveStatus = "unverified-source-field" }
quests[32266] = { id = 32266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manamanifestationen", description = "Manageister sind bösartige Kreaturen. Klein und leicht zu unterschätzen, aber eine tödliche Bedrohung für unsere Magiewirker. Die Kirin Tor lassen zu, dass diese Schädlinge sich über die ganze Violette Erhebung verbreiten.\n\nWir müssen vorsichtig mit ihnen umgehen. Einzeln sind sie leicht zu bewältigen, aber in Gruppen werden sie zu einer ganz neuen Herausforderung.\n\nGeht zur Violetten Erhebung und lichtet ihre Reihen.", sourceObjective = "Tötet 9 Manageister der Kirin Tor.", completion = "Dieses Problem werden wir nicht an einem Tag los, aber Ihr habt uns einen großen Dienst erwiesen, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32267] = { id = 32267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliches Portal beim Lager zerstören (einströmende Angreifer, verteidigt, kann vom Feind benutzt werden)" }
quests[32268] = { id = 32268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktische Manabomben", sourceObjective = "Bringt jeweils eine taktische Manabombe an einem Schiff der Allianz, bei den Versorgungsgütern der Allianz und beim Konstruktritual an.", completion = "Ich bin sicher, dass Jaina wegen der Benutzung selbst dieser kleineren Manabomben vor Wut schäumt. Geschieht ihr Recht.\n\nDalaran war meine Heimat, bevor ihre Großeltern auch nur geboren waren. Mit welchem Recht hat sie mich aus meiner Heimat vertrieben?", sourceObjectiveStatus = "unverified-source-field" }
quests[32269] = { id = 32269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung zerstören", description = "Wir müssen die Kirin Tor und ihren Tagesablauf genauestens überwachen. Normalerweise wäre das einfach. Wir würden einen Spion einschleusen und ihn Bericht erstatten lassen.\n\nWir sind allerdings auf ein kleines Problem gestoßen, mit dem Ihr uns helfen könnt, wie ich glaube.\n\nDie Schutzzauber der Kirin Tor sind verstärkt worden. Es ist praktisch unmöglich, jemanden hinter die Grenze zu bekommen. Wenn sie deaktiviert werden würden, könnten wir uns vielleicht einschleichen, bevor sie repariert werden können.", sourceObjective = "Zerstört 6 Schutzzauber der Kirin Tor.", completion = "Gute Arbeit, {class}. Mit Eurer Hilfe konnte ich erfolgreich einige Spione hinter die feindlichen Linien schmuggeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[32270] = { id = 32270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Minen in der Nähe des feindlichen Lasgers zerstören (stupst sie mit 'nem Stock :P)" }
quests[32271] = { id = 32271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legt Minen um das Lager (mit modernster Blitzkriegstechnik)" }
quests[32272] = { id = 32272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beschwörungsritual beim feindlichen Lager beginnen und verteidigen" }
quests[32273] = { id = 32273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörungskreise im feindlichen Lager zerstören" }
quests[32274] = { id = 32274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bewohner von Ihgaluk", description = "Die Skumklingen bedrohen unsere Leute, aber mit unverhohlenem Gemetzel zu reagieren, wäre eine Überreaktion.\n\nEine vernünftigere Reaktion auf diese Bedrohung wäre es, einige ihrer Stammesanführer zu töten. So erleiden sie weniger Blutvergießen und werden dennoch unsere Grenzen respektieren.", sourceObjective = "Tötet einen Schläger der Skumklingen, einen Saurierpriester der Skumklingen und einen Meerdrachen der Skumklingen.", completion = "Ich kenne den wahren Preis von Blutvergießen. Ich kenne den Preis des Krieges.\n\nEs wäre einfacher, unsere Angreifer blind zu massakrieren, bis sie aufgeben. Aber wäre das richtig?", sourceObjectiveStatus = "unverified-source-field" }
quests[32275] = { id = 32275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod mit chirurgischer Präzision", description = "Die Zandalari bilden Himmelsschreier zu wilden Bestien der Lüfte aus. Die Geisterbinder verlangen, dass ihnen dazu unzählige Opfer – unserer Leute — gebracht werden. Die Jaguarkrieger wagen sich immer näher an das Herz unseres Lagers.\n\nMacht sie in Za'Tual ausfindig und beseitigt diese Bedrohung.", sourceObjective = "Tötet 3 Geisterbinder der Zandalari, 3 Bestienrufer der Zandalari und 3 Jaguarkrieger der Zandalari.", completion = "Ich werde weiter keine Ruhe finden, bis die Bedrohung beseitigt ist, aber Eure Hilfe bringt uns diesem Ziel näher. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32276] = { id = 32276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mauer muss weg!", description = "Die Zeit ist gekommen. Unsere Stellung ist gut genug befestigt, sodass wir es riskieren können, in die Behausung des Donnerkönigs vorzudringen. Leider sieht es nicht so aus, als ob er dieses Tor in nächster Zeit öffnen wird.\n\nIch vermute also, dass wir uns unser eigenes Tor schaffen müssen. Lasst es mich wissen, wenn Ihr bereit seid, {name}.", sourceObjective = "Sprecht mit Lor'themar Theron und dringt dann in die untere Stadt vor, um sie für die Horde zu erobern.", completion = "Mit Eurer Hilfe sind wir unserem Ziel einen riesigen Schritt näher gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32277] = { id = 32277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Lüfte!", description = "Wir können die Pterrorschwinge, die Ihr gefunden habt, benutzen, um den Mogu einen entscheidenden Schlag zu versetzen.\n\nIhre Bergbauarbeiten sind empfindlich gegen Luftangriffe und Eure Pterrorschwinge ist das einzige Tier in unserem Besitz, das ohne Probleme dorthin gelangen kann.\n\nSagt mir Bescheid, wenn Ihr bereit seid!", sourceObjective = "Verschafft Euch Zugang zu den Blitzaderminen.", progress = "Es ist an der Zeit, Eure Mission zu beginnen!", completion = "Unglaubliche Arbeit. Das bietet uns eine monumentale Gelegenheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32278] = { id = 32278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschlossenes Handeln", description = "Kriegsschiffe der Zandalari plündern die Meere um diese Insel herum. Sie bringen Soldaten und Kriegsbestien aus Zandalar, um Lei Shens Armeen aufzustocken.\n\nWenn wir die Werft des Palastes in unseren Besitz bringen können, ist die Versorgungsroute des Donnerkönigs abgeschnitten, und Euer Standort hier ist gesichert.\n\nIch habe einen Plan, um genau das zu bewerkstelligen, und wir werden keine ganze Armee dazu brauchen.", sourceObjective = "Infiltriert den Sturmgepeitschten Hafen und öffnet das Tor zum Hof von innen. Sprecht mit Taoshi, um die Mission zu beginnen.", completion = "Großartige Arbeit! Nun da dieses verdammte Kriegsschiff außer Gefecht ist, wird die Bombardierung unserer Truppen an der Küste aufhören.\n\nTaran Zhu hat mir mitgeteilt, dass die Shado-Pan den Sturmgepeitschten Hafen bewachen werden, sodass die Sonnenhäscher ihre Ressourcen anderweitig für den Angriff nutzen können. Taoshi wird da sein. Ich bin sicher, dass sie gern wieder mit Euch arbeiten würde.\n\nWir sind für Euren Beitrag dankbar, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[32279] = { id = 32279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz von Shan'Bu", description = "Vor langer Zeit fand Lei Shen ein Gelege seltener Sturmdracheneier. Eine dieser Kreaturen - Nalak - war besonders brutal, also nahm Lei Shen sie an sich.\n\nShan'Bu, der Diener des Donnerkönigs, arbeitet daran, Lei Shens Drachen Nalak wiederzuerwecken.\n\nWir müssen Shan'Bu besiegen und ihn davon abhalten, den Drachen wiederzuerwecken, wenn wir dazu in der Lage sind.", sourceObjective = "Besiegt Shan'Bu.", completion = "Gut gemacht, {name}. Shan'Bus Sturz wird die Mogu schwächen, und man wird sich Eurer Heldentaten erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[32280] = { id = 32280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Metallokalypse", description = "Ihr hattet einen guten Start. Aber jetzt ist es an der Zeit, ihrer Operation einen echten Rückschlag zu versetzen.\n\nMacht Metallfürst Mono-Han ein Ende. Er ist in der Mine.", sourceObjective = "Tötet Metallfürst Mono-Han außerhalb der Blitzadermine auf der Insel des Donnerkönigs.", sourceObjectiveStatus = "unverified-source-field" }
quests[32281] = { id = 32281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Fleischschmieds", description = "Der Mogu, der für die Folter der Agenten verantwortlich ist, Fleischschmied Goju, befindet sich außerhalb der Mine.\n\nIhn zu töten wäre die einzig gerechte Strafe für das, was er Euren Agenten angetan hat.", sourceObjective = "Tötet Fleischschmied Goju außerhalb der Blitzadermine auf der Insel des Donnerkönigs.", sourceObjectiveStatus = "unverified-source-field" }
quests[32282] = { id = 32282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compyknüppler", description = "Die Raptoren und Compys der Zandalari stellen eine erhebliche Bedrohung für unsere Truppen dar. Sie sind hervorragende Jäger und können ihre Beute über große Entfernungen verfolgen. Zudem enden ihre Angriffe oft tödlich, wenn sie ihre Opfer überraschen können.\n\nIch möchte, dass Ihr Euch in die Bestienpferche begebt und ihre Zahl verringert. Wir müssen sicherstellen, dass sie sterben bevor ihre Ausbildung abgeschlossen wurde.", sourceObjective = "Tötet 5 Raptoren und 10 abgerichtete Compys in den Bestienpferchen.", progress = "Man kann über die Zandalari sagen, was man will - aber niemand kommt an ihre Fähigkeit heran, selbst die widerwärtigsten Kreaturen zu geschulten Waffen auszubilden.", completion = "Kurz nach unserer Ankunft hier haben wir drei gute Soldaten verloren. Im Schlaf von Compys getötet, die sich in ihr Zelt geschlichen hatten. In manchen Nächten höre ich noch immer ihre Schreie.", sourceObjectiveStatus = "unverified-source-field" }
quests[32283] = { id = 32283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loasaurus", description = "Die Zandalari haben einen Weg gefunden, um Loa an ihre Bestien zu binden, was den Tieren beeindruckende und tödliche Kräfte verleiht.\n\nWir müssen das beenden.\n\nSucht in den Bestienpferchen nach einem Loasprecher und tötet ihn. Es sollte Euch möglich sein, einen zu finden, wenn Ihr Ausschau nach ihren leuchtenden Reittieren haltet.\n\nDiese Untaten dürfen einfach nicht weitergehen.", sourceObjective = "Bezwingt einen Loasprecher.", completion = "Gut gemacht, Champion. Diese Bestien sind stark genug. Sie müssen nicht auch noch von einem verärgerten Geist besessen sein, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[32284] = { id = 32284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemand, den Ihr treffen solltet", sourceObjective = "Findet Chen Sturmbräu in Binan. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", progress = "Es steht mir nicht zu, in diesem Krieg eine Seite zu wählen. Doch ich werde einen Troll, der zu Lebzeiten so viel geleistet hat, nicht ohne Weiteres aufgeben.", completion = "Ah! Ihr habt meine Nachricht erhalten. Sehr gut. Vol'jin ist dem Tod nahe, und ich brauche Eure Hilfe, um seine Wunden zu heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32285] = { id = 32285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schlaflose Legion", description = "Die Shan'ze erwecken eine Armee aus den Statuen in der Mitte der Insel, eine Armee, die unsere Verteidigung Tag und Nacht auf die Probe stellt. Zerstört jede wandelnde Statue, die Ihr zu Gesicht bekommt. Unsere Verteidiger wären Euch sehr dankbar.", sourceObjective = "Tötet 6 animierte Krieger.", sourceObjectiveStatus = "unverified-source-field" }
quests[32286] = { id = 32286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutsucher der Mogu töten (wandernde Zweirgruppen, die Späher aktiv bekämpfen und Rituale an Leichen durchführen)" }
quests[32287] = { id = 32287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde unter dem Turm", description = "Im Düstermoor halten sich Mogu auf, die die Statuenarmee beim Turm erwecken. Lor'themar will, dass sie sterben. Ich glaube, Ihr könnt das erledigen.", sourceObjective = "Tötet 7 Mogu der Shan'ze im Düstermoor.", sourceObjectiveStatus = "unverified-source-field" }
quests[32288] = { id = 32288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung stärken", description = "Diese Insel birgt für uns viele Gefahren. Auf allen Seiten lauern Bedrohungen. Wir müssen unsere Stellung an dieser Küste um jeden Preis halten.\n\nRings um das Morgensucherkap sind Schutzzauber aufgestellt worden. Sie werden grundsätzlich Schaden verursachen, aber ihre Angriffe sind nicht tödlich.\n\nJetzt ist der falsche Zeitpunkt, um Gnade zu zeigen, {race}. Die Schutzzauber müssen tödlich sein!\n\nGeht und ladet die Schutzzauber auf, die unser Lager umgeben.", sourceObjective = "Ladet 6 Schutzzauber der Sonnenhäscher auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[32289] = { id = 32289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pläne erbeuten, Kapitän töten" }
quests[32290] = { id = 32290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungenutzt" }
quests[32291] = { id = 32291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz von Shan'Bu", description = "Tötet Shan'Bu" }
quests[32292] = { id = 32292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiede voraus!", description = "Die Schmiede liegt vor Euch und mit ihr das Herz der Moguschmiedekunst.\n\nEin wenig weiter befindet sich der Mogutorwächter, der den Schlüssel zum nächsten Teil der Stadt in seinen Händen hält.\n\nZeit für den Vorstoß!", sourceObjective = "Tötet den Meister der Schmiede und sammelt ein Kodexfragment von Fleischschmied Hoku auf der Insel des Donners ein.", progress = "Nun?", completion = "Gute Arbeit. Was Ihr heute getan habt, bringt uns einen Schritt näher an unser endgültiges Ziel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32293] = { id = 32293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Knochen", description = "Meine Späher haben zwischen den Knochen westlich der Ihgalukklamm einen gefährlichen Zandalari entdeckt. Ich brauche jemand Fähigen, der dafür sorgt, dass er beseitigt wird. Traut Ihr Euch das zu?", sourceObjective = "Tötet Zur'chaka den Knochenformer.", completion = "Es ist gut, einen Mann in der Nähe zu haben, auf den ich mich verlassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[32294] = { id = 32294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenregen", description = "Wir haben einen Anführer der Zandalari auf der mittleren Treppe entdeckt. Wir müssen ihn vernichten, bevor wir ins Lager zurückkehren.\n\nWürdet Ihr das erledigen?", sourceObjective = "Tötet Zur'chaka den Knochenformer.", sourceObjectiveStatus = "unverified-source-field" }
quests[32295] = { id = 32295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ungewöhnlicher Foliant", description = "Der Foliant wurde in einer kunstvollen, ausladenden Schrift geschrieben, die von den Seiten hervorzutreten scheint. Sie ähnelt entfernt Dämonisch, doch die Symbole sind viel aufwendiger als alle, die Ihr je zu Gesicht bekommen habt.\n\nVielleicht kann Euch einer Eurer dämonischen Begleiter mehr darüber sagen.", sourceObjective = "Sprecht mit Euren dämonischen Dienern, um mehr über die Ursprünge des Folianten zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[32296] = { id = 32296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schätze des Donnerkönigs", description = "Meine Späher sind mit der Meldung zurückgekehrt, dass mehr und mehr Schätze aus Lei Shens Grab in die Zitadelle geschafft werden. Ich habe einen geheimen Eingang gefunden, aber eine Tür hält uns davon ab, die Lieferung abzufangen. Wenn dieser Raubzug ein Erfolg werden soll, müssen wir uns einen Schlüssel beschaffen, den nur die engsten Vertrauten von Lei Shens Truppen bei sich haben.\n\nFalls Ihr einen solchen Schlüssel findet, bringt ihn mir.\n\nIhr könnt behalten, was auch immer wir bei unserem Raubzug finden. Ich will einfach nur sicher sein, dass diese Lieferung Lei Shen nie erreicht.", sourceObjective = "Sprecht mit Taoshi, um die Zitadelle des Donnerkönigs zu betreten. Beschafft ihr dort einen Schlüssel zu Lei Shens Palast, um den zeitbegrenzten Beutezug auf seine Schatzlieferung zu beginnen.", progress = "Wir müssen Lei Shen auf jede Art sabotieren, die uns zur Verfügung steht. Alles, um den Anstieg seiner Macht zu behindern. Alles, um seine Armeen nicht wachsen zu lassen.\n\nWenn das bedeutet, dass wir zum Straßenraub übergehen müssen, kann ich auch damit leben.", completion = "Das war kein vollständiger Fehlschlag. Trotzdem müssen wir es nächstes Mal besser machen.\n\nDanke, dass Ihr uns diesen Schlüssel besorgt habt. Ohne Euch hätte der Angriff nicht gestartet werden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[32297] = { id = 32297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terrorhorn oder Teufelssaurier", description = "Wir haben eine Gelegenheit, die Kriegsmaschinerie der Zandalari ins Stocken zu bringen und gleichzeitig etwas Spaß zu haben.\n\nIn diesen Bestienpferchen werden ein Teufelssaurier und ein Terrorhorn mit Rüstung ausgestattet, während ihr Geist den Zaubern der Zandalari unterworfen ist.\n\nGeht in das Lager und unterbrecht eines dieser Bindungsrituale. Es ist egal welches, tötet einfach nur diejenigen, die die Kreatur im Zaum halten. Das sollte genügen, um das voll gerüstete Tier auf Verwüstungstour durch ihr Lager zu schicken. Dann lehnt Euch einfach zurück und genießt das Spektakel.", sourceObjective = "Unterbrecht ein Bindungsritual, indem Ihr alle Trolle tötet, die ein starrsinniges Terrorhorn oder einen widerspenstigen Teufelssaurier umringen.", progress = "Und, wofür habt Ihr Euch entschieden – Teufelssaurier oder Terrorhorn?", completion = "Es gibt wenige Dinge auf der Welt, die unterhaltsamer sind, als eine urzeitliche Bestie dabei zu beobachten, wie sie durch ein feindliches Lager wütet.\n\nWenn die Zeiten nicht so finster wären, würde ich es erwägen, Karten für eine solche Veranstaltung zu verkaufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32298] = { id = 32298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurierstark", description = "Die Zandalari verwenden eine ganze Batterie von Fetischen und Amuletten, um ihre Wildtiermenagerie im Zaum zu halten.\n\nBei diesem Spielchen können wir mitspielen.\n\nIch möchte, dass Ihr einige dieser Fetische auftreibt und ihre Wirkung auf die verschiedenen Tiere in den Bestienpferchen untersucht.\n\nNotiert Euch aufmerksam, wie welches Tier auf welchen Fetisch reagiert. Gebt Eure Untersuchungen dann an mich weiter.\n\nVielleicht kann uns das genau den Vorteil verschaffen, den wir gegen die Zandalari benötigen.", sourceObjective = "Findet Saurierfetische und wendet sie auf 5 Raptoren, Compys, Himmelskreischer oder Terrorhörner in den Bestienpferchen an.", completion = "Sehr interessante Resultate. Ich bin mir sicher, dass es hier einen Magier gibt, der sich auf die Details stürzen wird. Ich für meinen Teil bin froh, mich am Geschrei von Trollen zu erfreuen, die von ihren eigenen Bestien angegriffen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32299] = { id = 32299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur leichte Aufräumarbeiten", description = "Das ist keine glamouröse Aufgabe. Lasst mich ganz direkt sein.\n\nDie Saurok der Skumklingen häufen all ihren Dreck in einem Tümpel mitten in ihrem Dorf auf. Dieser Dreck ist so konzentriert und ranzig, dass er sich zu einer bewegten, belebten Masse entwickelt hat.\n\nDie Saurok können ihren Drecktümpel ja gern behalten, aber da er sich außerhalb des Dorfes ausbreitet würde ich sagen, dass es an der Zeit ist einzuschreiten.", sourceObjective = "Zerstreut 75 Dreckstücke, indem Ihr den wabernden Dreck in der Ihgalukklamm tötet.", completion = "Aufgaben wie diese machen mich dankbar dafür, dass ich den Großteil meiner Nase im Grab gelassen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[32300] = { id = 32300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwaffnende Ironie", description = "Nun, es sieht so aus, als hätte Lady Prachtmeer beschlossen, unsere eigenen Waffen gegen uns zu verwenden. Unsere Schutzzauber haben angezeigt, dass mehrere Spione mit taktischen Manabomben durch unsere Verteidigung geschlichen sind.\n\nWenn diese Bomben weniger gefährlich wären, würde ich beinahe über die Ironie lachen.\n\nSucht diese Bomben und entschärft sie. Unsere Zauber sagen uns, dass eine bei den Schiffen der Horde im Norden, eine an einer Brücke zur Hauptinsel und eine bei unseren Seherkristallen auf der östlichen Seite des Kaps ist.", sourceObjective = "Entschärft die taktischen Manabomben an den Schiffen der Horde, den Seherkristallen und der Brücke am Morgensucherkap.", completion = "Gute Arbeit. Die wahre Ironie an der Sache ist, dass es uns bei normalen Bomben viel schwerer gefallen wäre, sie zu entdecken. Irgendeine gnomische Teufelei hätte unsere Unternehmung hier beenden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[32301] = { id = 32301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Feinde", description = "Es ist kaum zu glauben, dass wir einst auf derselben Seite gekämpft haben! Der Verrat der Sonnenhäscher hat uns alle überrascht. Nie wieder!\n\nSie haben uns ihre wahre Natur offenbart. Sich auf die Seite Garroshs und seines Wahnsinns zu stellen, hat sie dem Tod geweiht.\n\nTötet jeden Agenten der Sonnenhäscher, den Ihr finden könnt. Wir werden ihnen hier keine Gnade zeigen.", sourceObjective = "Tötet auf der Insel des Donners 10 Agenten oder Spielercharaktere, die für die Sonnenhäscher arbeiten.", completion = "Ihr habt den Truppen der Sonnenhäscher hier ordentlich zugesetzt. Wie Ungeziefer werden immer mehr davon auftauchen. Wir müssen jederzeit bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32302] = { id = 32302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "De-Konstruktion", description = "Die Konstrukte der Kirin Tor sind bestenfalls primitiv. Dennoch stellen sie eine Bedrohung dar.\n\nGeht zur Violetten Erhebung und nehmt Jainas lächerliche Kriegsmaschinen auseinander. Zeigt den Kirin Tor, wie leicht sie zu besiegen sind!\n\nDas wird eine Botschaft an die Kirin Tor, die sie nicht einfach ignorieren können.", sourceObjective = "Zerstört 3 Konstrukte der Kirin Tor in der Nähe der Violetten Erhebung.", completion = "Die Konstrukte sind gefallen? Gut!\n\nWir werden Jaina und die Kirin Tor bei jeder Gelegenheit daran erinnern, dass man die Sonnenhäscher nicht abtun kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[32303] = { id = 32303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für den Krieg geschaffen", description = "Jaina glaubt, dass diese Schlacht leicht zu gewinnen sei. Ich werde ihr zeigen, wie sehr sie sich irrt!\n\nDie Kirin Tor haben eine Waffe mit sich gebracht, die zerstört werden muss. Der arkane Zerstörer ist ein großes Konstrukt, das in der Schlacht das Blatt zu ihren Gunsten wenden könnte.\n\nDiese Monstrosität zu zerstören, würde Prachtmeer eine sehr klare Botschaft senden.", sourceObjective = "Tötet den arkanen Zerstörer.", completion = "Ich wünschte ich könnte da sein und Prachtmeers Gesicht sehen, wenn sie um den Verlust ihrer Todesmaschine trauert!\n\nWir können uns sicher sein, dass sie eine neue bauen wird, aber wenigstens haben wir ihr einen Rückschlag versetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[32304] = { id = 32304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Anerkennung", sourceObjective = "Eure Präsenz auf dem Schlachtfeld ist nicht zu leugnen. Ich möchte Euch dies als zusätzliche Anerkennung für Eure Leistungen überreichen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32305] = { id = 32305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel zu stark", description = "Die Kirin Tor benutzen Manafokusse, um ihre Truppen zu stärken. Wir können nicht zulassen, dass das weitergeht.\n\nIhr könnt diese Fokusse am Randbereich der Violetten Erhebung finden. Benutzt diesen Manakristall, um so viele wie nur möglich zu zerstören.\n\nJeder zerstörte Manafokus ist ein kleiner Sieg für unsere Sache.", sourceObjective = "Zerstört 7 Manafokusse auf der Violetten Erhebung.", completion = "Großartige Arbeit, {class}! Es wird Tage dauern, bis sie diese Fokusse wieder aufgebaut haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[32306] = { id = 32306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufspüren der Holzsammlung" }
quests[32307] = { id = 32307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leser der toten Sprache", description = "Kehrt in Eure Hauptstadt zurück und findet einen Hexenmeisterlehrer, der womöglich mehr über den Kodex weiß.", sourceObjective = "Bringt den Kodex zu einem Hexenmeisterlehrer in Eurer Hauptstadt.", completion = "Was... wie tief habt Ihr Euch in die Schatten begeben müssen, um das hier zu finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[32309] = { id = 32309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte der Sechs Meister", description = "Dieses Buch könnte genau das sein, wonach wir gesucht haben...\n\nWie gut kennt Ihr Euch mit dem Rat der Schwarzen Ernte aus, {name}?\n\nNachdem Todesschwinge besiegt war, versammelten sich sechs der mächtigsten Hexenmeister, um allen Hexenmeistern die fortschrittliche Magie zu lehren, die wir unseren besiegten Feinden gestohlen hatten.\n\nSchaut Euch einmal diesen Folianten neben mir an...", sourceObjective = "Lest das erste Kapitel des Erbes der Meister.", progress = "Nun, was haltet Ihr davon?", completion = "Ihr seid bereit, mehr zu lernen...", sourceObjectiveStatus = "unverified-source-field" }
quests[32310] = { id = 32310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte der Sechs Meister", description = "Dieses Buch könnte genau das sein, wonach wir gesucht haben...\n\nWie gut kennt Ihr Euch mit dem Rat der Schwarzen Ernte aus, {name}?\n\nNachdem Todesschwinge besiegt war, versammelten sich sechs der mächtigsten Hexenmeister, um allen Hexenmeistern die fortschrittliche Magie zu lehren, die wir unseren besiegten Feinden gestohlen hatten.\n\nSchaut Euch einmal diesen Folianten neben mir an...", sourceObjective = "Lest das erste Kapitel des Erbes der Meister.", progress = "Nun, was haltet Ihr davon?", completion = "Jetzt seid Ihr bereit, mehr zu lernen...", sourceObjectiveStatus = "unverified-source-field" }
quests[32311] = { id = 32311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Musterung", description = "Nachdem der Rat von seiner Reise zurückgekehrt war, teilten sie das Wissen, das sie erlangt hatten, mit allen Hexenmeistersekten.\n\nKurz darauf verschwanden sie jedoch...\n\n{name}! Der Foliant, den Ihr besitzt, könnte genau das sein, mit dem wir sie überzeugen können, sich unserem Angriff auf die Allianz anzuschließen!\n\nFindet General Nazgrim bei der Herrschaftsfeste und überzeugt ihn von der Wichtigkeit Eurer Mission.", sourceObjective = "Findet General Nazgrim bei der Herrschaftsfeste in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[32312] = { id = 32312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Musterung", description = "Nachdem der Rat von seiner Reise zurückgekehrt war, teilten sie das Wissen, das sie erlangt hatten, mit allen Hexenmeistersekten.\n\nKurz darauf verschwanden sie jedoch...\n\n{name}! Der Foliant, den Ihr besitzt, könnte genau das sein, mit dem wir sie überzeugen können, sich unserem Angriff auf die Horde anzuschließen!\n\nFindet Admiral Taylor in der Löwenlandung und überzeugt ihn von der Wichtigkeit Eurer Mission.", sourceObjective = "Findet Admiral Taylor in der Löwenlandung in der Krasarangwildnis.", sourceObjectiveStatus = "unverified-source-field" }
quests[32313] = { id = 32313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt Helheim", description = "{name}... Ihr habt recht gehört. Kriegshäuptling Garrosh hat mich beauftragt, diesen Rat der Schwarzen Ernte zu finden.\n\nLeider habe ich erfahren, dass uns die Allianz voraus ist. Ich habe auch gehört, dass ein menschlicher Hexenmeister namens Harim Helheim Informationen besitzt, die uns helfen, den Rat zu finden.\n\nBegebt Euch zur Löwenlandung, infiltriert ihre Basis und besorgt die Dokumente, bevor Helheims Bote aufbricht. Zeigt Helheim keine Gnade.", sourceObjective = "Besorgt den zweiten Teil des Erbes der Meister von Harim Helheim.", sourceObjectiveStatus = "unverified-source-field" }
quests[32314] = { id = 32314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Selenora", description = "{name}... Ihr habt recht gehört. König Varian hat mich beauftragt, diesen Rat der Schwarzen Ernte zu finden.\n\nLeider sucht auch die Horde nach ihm. Einer meiner Spione berichtete kürzlich, dass Schattenbeschwörerin Selenora den zweiten Teil des Tagebuchs besitzt.\n\nBegebt Euch zur Herrschaftsfeste, tötet Selenora und besorgt alles, was sie bei sich trägt.", sourceObjective = "Besorgt das zweite Kapitel des Erbes der Meister von Schattenbeschwörerin Selenora in der Herrschaftsfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[32315] = { id = 32315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anduins Bitte", description = "Ah, Ihr seid genau die Art {class}, die ich suche. Ich habe einen dringenden Brief des jungen Prinzen Anduin erhalten.\n\nEr spielt den Gastgeber für seinen Vater König Wrynn und einige weitere Würdenträger der Allianz am Schrein der Sieben Sterne im Tal der Ewigen Blüten.\n\nNach seinen letzten Botschaften zu urteilen, scheint sich in der Stadt Schlimmes zuzutragen.\n\nBitte brecht sofort auf und sprecht mit ihm. Ich habe hier in der Löwenlandung noch einiges zu erledigen, werde aber schon bald zu Euch stoßen.\n\nSprecht mit Fennie, wenn Ihr einen Flug ins Tal benötigt.", sourceObjective = "Findet Anduin beim Schrein der Sieben Sterne. Sprecht mit Fennie Hornsturz in der Löwenlandung bezüglich einer Transportmöglichkeit.", completion = "Seid gegrüßt, {class}. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[32316] = { id = 32316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz der Allianz", description = "Wie konnte das nur passieren, {name}? Haben unsere Leute nach all dem, was wir hier in Pandaria durchgemacht haben, noch immer nicht aus ihren Fehlern gelernt?\n\nBranns Expedition ist neulich aus Mogujia zurückgekehrt und hat zu Untersuchungszwecken eine Sha-Probe mitgebracht.\n\nIch hatte so meine Bedenken, was dieses Vorhaben anbelangte, und meine schlimmsten Befürchtungen haben sich als berechtigt erwiesen.\n\nDas Sha ist aus seiner Eindämmung ausgetreten. Ich muss wohl nicht erwähnen, welche Schrecken die Ankunft des Sha im Herzen des Tals bedeutet.\n\nWir müssen alles Sha, das wir finden können, neutralisieren, und zwar schnell!", sourceObjective = "Nehmt es mit 6 Sha-berührten Fußsoldaten auf. Solltet Ihr Prinz Anduin verlieren, sprecht mit ihm beim Kaiserlichen Kontor.", progress = "Wir müssen dieses Land und sein Volk vor dem Einfluss des Sha schützen.", completion = "Ich sehe, Ihr und mein Sohn habt gute Arbeit geleistet. Danke, dass Ihr unsere Sache hier im Tal so vortrefflich vertretet.", sourceObjectiveStatus = "unverified-source-field" }
quests[32317] = { id = 32317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach den Seelensteinen", description = "{name}, nehmt dies – es ist das Tagebuch von Jubeka Schattenbruch.\n\nLest es und findet heraus, wo sie hingegangen ist.\n\nErlangt ihre Seelensteine und setzt sie ein, um Jubeka zu finden.", sourceObjective = "Lest Jubekas Tagebuch und nutzt die in ihm enthaltenen Hinweise, um die vier Seelensteinfragmente zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32318] = { id = 32318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regeneration will Weile haben", description = "Vol'jin wäre tot, wenn er kein Troll wäre. Seine Regenerationsfähigkeit ist beeindruckend, aber sie wird durch ein Gift behindert.\n\nWir müssen dieses Gift eliminieren, damit er den Schaden regenerieren kann.\n\nErhebt Euch in die Lüfte und brecht gen Südosten auf. Auf den Gipfeln des Versteckten Horsts werdet Ihr Nadelgeister antreffen. Bringt mir die härtesten ihrer Nadeln, die Ihr finden könnt.\n\nMit ihnen kann ich eine Akupunkturtechnik versuchen, die seinen Körper von dem Gift reinigen und seine Regeneration beschleunigen sollte.", sourceObjective = "Sammelt 10 starke Nadeln.", progress = "Nur meine Kräuter halten Vol'jin noch am Leben. Ich wage es nicht, von seiner Seite zu weichen.", completion = "Sehr gut. Die hier sollten genau das Richtige sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[32319] = { id = 32319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Thrall!", description = "<Vol'jin öffnet halb ein Auge und bewegt die Lippen, als setze er zu sprechen an. Obwohl er keinen Ton herausbringt, versteht Ihr zwei Worte.>\n\nSucht Thrall.\n\n<Mit Anstrengung drückt Vol'jin Euch einen Ruhestein in die Hände, bevor er ohnmächtig wird.>", sourceObjective = "Spürt Thrall mithilfe von Vol'jins Ruhestein auf.", progress = "Ihr seid von weit her zu mir gekommen, {race}. Sprecht.", completion = "<Thrall starrt auf den Stein, den Ihr ihm überreicht habt.>\n\nVol'jins Ruhestein? Ist es schon so weit gekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[32320] = { id = 32320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde ist wie eine Familie", sourceObjective = "Eskortiert Thrall zu den Echoinseln.", completion = "Vol'jin hat mir schon viele Male das Leben gerettet. Mit ansehen zu müssen, wie meine eigenen Kor'kron gegen sein Volk gerichtet werden, schmerzt mich mehr als ich in Worte fassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[32321] = { id = 32321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Affenkönig", description = "Seit die Horde die Götterglocke an sich gerissen hat, suche ich nach einem Mittel, ihrer Macht etwas entgegenzusetzen.\n\nMeine Nachforschungen haben mich zu diesem Grab geführt. Ich werde es betreten. Wenn Ihr mir folgt, werde ich Euch den Rest unterwegs erzählen.\n\nFalls wir getrennt werden sollten, treffen wir uns hier am Eingang zum Grab wieder. Sprecht mit mir, wenn Ihr so weit seid.", sourceObjective = "Helft Anduin Wrynn, den Affenkönig im Tal der Kaiser zu finden.", completion = "Ihr fragt nach dem Affenkönig?\n\nLasst uns mal sehen, vielleicht singt Ihr fröhlich.\n\nWer seid Ihr denn, so klein und öde?\n\nEure Sache ist ein Schnarcher, wirklich blöde.\n\nDrei Rätsel ich Euch frage,\n\nsie sind eine Aufgabe.\n\nLöst sie alle schön am Stück,\n\nund vielleicht bring' ich Eurer Sache Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[32324] = { id = 32324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht das Signal", description = "Die Fragmente des Seelensteins fügen sich in Eurer Hand wieder zu einem Ganzen zusammen.\n\nDoch seltsamerweise befindet sich keine Seele in diesem Stein. Stattdessen scheint er Macht von einem Ort im Schattenmondtal zu beziehen. Wenn Ihr Euch nach Osten wendet, fühlt Ihr, wie die Verbindung bis zu einem Punkt hinter den Bergen besteht, bis zu den Toren des Schwarzen Tempels.", sourceObjective = "Folgt dem Seelenstein zu den Toren des Schwarzen Tempels.", sourceObjectiveStatus = "unverified-source-field" }
quests[32325] = { id = 32325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration des Schwarzen Tempels", description = "Jubekas Seelenstein hat Euch eindeutig hierher zum Schwarzen Tempel geführt.\n\nDoch es ist weiterhin unklar, warum.\n\nDie einzige Möglichkeit, mehr zu erfahren, ist, den Tempel zu betreten und herauszufinden, warum sie hier waren.", sourceObjective = "Sucht Jubekas Mal am Haupteingang des Schwarzen Tempels. Sprecht bei der Tempelspitze mit Jubeka, nachdem Ihr eingetreten seid.", completion = "Ihr habt mehr für diese Welt getan, als Ihr wisst, {class}. Es ist... schon eine Schande, dass Kanrethad solch ein Ende fand. Eine Schande, aber unvermeidlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[32326] = { id = 32326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringen", description = "{name}! Ihr seid genau <der Richtige/die Richtige>.\n\nWir wissen, wo die Allianz die Götterglocke versteckt hält. Wir haben bereits einen Agenten in feindliches Territorium geschickt, Ihr müsst ihm nur noch helfen, seine Mission durchzuführen.\n\nMacht Euch fertig, {name}. Darnassus heißt Euer Ziel.", sourceObjective = "Benutzt das Sonnenhäscherportal in der Herrschaftsfeste, um einen Teleport nach Darnassus zu sichern.", completion = "{name}! Ich bin ja so froh, dass Nazgrim Euch ausgewählt hat.\n\nDie Horde hat großen Aufwand betrieben, um Euch durch Jainas Fallen hierher zu schleusen. Unsere Täuschung so nahe bei Darnassus aufrechtzuerhalten ist ziemlich aufwendig.\n\nAußerdem setzen die Sonnenhäscher von Dalaran ihren Neutralitätsstatus aufs Spiel, indem sie der Horde bei dieser Operation helfen.\n\nMit anderen Worten: Wir erwarten nur das Allerbeste von Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[32327] = { id = 32327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission in Darnassus", description = "Die Götterglocke ist in der Stadt. Wir wollen keine Szene machen, wir wollen nichts weiter als das Artefakt. Ich will, dass Ihr hineingelangt, OHNE erwischt zu werden. Das heißt keine Reittiere, kein Fliegen, kein Kämpfen.\n\nIch kann Euch Hilfe leisten. Ich werde Euch magisch tarnen, damit Ihr Euch in Verstohlenheit bewegen könnt. Außerdem werde ich Euch ein kleines Amulett geben, mit dem Ihr wohlbehalten zurückkehren könnt, falls Ihr in Schwierigkeiten geratet.\n\nBrecht jetzt auf, {name}. Zieht los, findet die Glocke und markiert sie, um sie mit Euch zurückzuteleportieren.", sourceObjective = "Findet die Götterglocke.\n\nIhr könnt mithilfe des Silbermondglücksbringers zu Fanlyr zurückkehren, wenn Ihr in Schwierigkeiten geratet.", progress = "Die Glocke, {name}!", completion = "Gut gemacht, {race}! Ich wusste, dass wir auf Euch zählen können.\n\nUnd nun runter von diesem elenden Baum.", sourceObjectiveStatus = "unverified-source-field" }
quests[32328] = { id = 32328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegreiche Rückkehr", description = "Das Portal an meiner Seite wird Euch wohlbehalten zur Herrschaftsfeste zurückbringen. Ich werde nach Euch zurückkehren - ich muss vor unserem Aufbruch unsere Spuren noch etwas verwischen, damit Prachtmeer nicht herausfindet, dass wir beteiligt sind.", sourceObjective = "Erstattet Nazgrim bei der Herrschaftsfeste in der Krasarangwildnis Bericht von Eurem Erfolg.", completion = "Ihr habt die Glocke gefunden! Und Fanlyr hat sie wie angewiesen zur Untersuchung nach Silbermond teleportiert? Die Horde wird guten Gebrauch davon machen.\n\nHeute habt Ihr der Horde einen großen Dienst erwiesen. Lok'tar, mein Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[32329] = { id = 32329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt meine Ergebnisse!", sourceObjective = "Sprecht mit Lor'themar Theron in Silbermond.", completion = "Der Kriegshäuptling \"verlangt\" Fortschritte? Seine Ungeduld wird der Sache mit jedem Befehl weniger zuträglich.\n\nSei dem wie es ist, Eure Erfahrung könnten wir gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32330] = { id = 32330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist in der Kiste?", description = "Wir versuchen, einem der Moguartefakte, die wir auf Garroshs Befehl untersuchen sollten, seine Geheimnisse zu entlocken. Allerdings wird jeder, der versucht, es magisch zu erforschen, von rohen, negativen Emotionen übermannt.\n\nIch habe den Erzmagier Aethas von den Sonnenhäschern um Hilfe gebeten, in der Hoffnung, dass er und Rommath dieses Rätsel lösen können. Sie haben ausdrücklich nach Euch gefragt - angeblich habt Ihr einschlägige Erfahrung.\n\nGeht zu der Kammer unter dem Platz der Weltenwanderer östlich von hier und findet heraus, ob Ihr ihnen behilflich sein könnt.", sourceObjective = "Helft Aethas und Rommath bei ihrem Experiment.", completion = "Es kann nicht mehr geduldet werden, dass Garrosh meine Leute so skrupellos benutzt. Ich wage gar nicht daran zu denken, was ohne Eure Hilfe hätte passieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[32331] = { id = 32331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kirin Tor", sourceObjective = "Tretet durch das Portal zum Purpursalon in der Löwenlandung und trefft Euch mit Anduin Wrynn.", completion = "Ich freue mich, Euch zu sehen. Auch wenn ich viel über Diplomatie gelernt habe, glaube ich, dass Jaina meine Taktik durchschaut.\n\nIch könnte Hilfe beim Lösen dieses Konflikts gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32332] = { id = 32332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erste Rätsel: Gnade", description = "Soso, Ihr weckt den Affenkönig wegen eines Hammers auf, hmmm? Drei Rätsel Ihr erst lösen müsst, auf dass der Hammer Euer ist!\n\nHier das erste Rätsel!\n\n\"Es singt ganz sanft ein Lied voll Gram,\n\nein Wesen, geschunden und ganz und gar lahm.\n\nJenseits der Mauer, tief unten im Süden,\n\nsucht es vor dem Ruf seines Meisters Frieden.\n\nEs wartet in finsterer Traurigkeit\n\nauf den, der es aus dem Bern befreit.\"\n\nBringt mir den ungezähmten Bern.", sourceObjective = "Sucht den Gegenstand, den der Affenkönig in seinem Rätsel beschrieben hat.", progress = "Ah, das kluge Dingens ist wieder da. Habt Ihr meinen Bern?", completion = "Ah! Bern! Frisch und ungezähmt. Musstet Ihr töten, um ihn zu bekommen? Natürlich musstet Ihr das.\n\nAuch wenn er nichts kosten mag, ungezähmter Bern ist gefährlich und könnte vielen den Tod bringen.\n\nGnade kommt in vielfältiger Form, wie Stacheln, Mantis und ein verfiddelter Sturm.", sourceObjectiveStatus = "unverified-source-field" }
quests[32333] = { id = 32333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das zweite Rätsel: Gefährten", description = "Ihr wollt die Götterglocke aufhalten? Zuerst brauchen wir den Schlaghammer.\n\nIhr wollt den Schlaghammer? Zuerst müssen wir Freunde sein.\n\nIhr wollt Freunde sein? Zuerst brauchen wir ein Metallbräu. \n\nIhr wollt ein Metallbräu? Zuerst müsst Ihr zum Schrein der Gefährten gehen.\n\nIhr wollt zum Schrein der Gefährten gehen? Toll! Der steht im Jadewald, südöstlich vom Tiankloster.\n\nLäutet den Gong und besorgt dem Affenkönig Gebräu, wenn Ihr schon dort seid. Ach... kann sein, dass Ihr darum kämpfen müsst.", sourceObjective = "Besorgt Metallbräu.", progress = "Ihr habt das Metallbräu?", completion = "Metallbräu ist stark und hält lange vor; die Art Gebräu, mit der man nach der Schlacht mit Kameraden anstößt.\n\nKaiser Shaohao und sein Affenkönig haben schon so manche Runde geschmissen. Viele Schlachten, viele gute Freunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[32334] = { id = 32334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dritte Rätsel: Stärke", description = "Der Hammer, den Ihr sucht, ist nicht für Kinder bestimmt,\n\ndenn wer ihn trägt, der großen Ärger auf sich nimmt.\n\nDer Affenkönig fordert einen Kräftetest,\n\nbevor dieses Werkzeug Euer ist.\n\nBeim Tempel des Weißen Tigers, da ist jemand,\n\nder prüfen will, ob Ihr seid gewandt.\n\nGeht durch das Haupttor und rechts die Rampe hinunter,\n\nkämpft mit dem Fiddel dort, der wartet ganz munter!", sourceObjective = "Besiegt den Herausforderer am Tigertempel.", completion = "Warum Duelliererei? Weshalb Alberei?\n\nIhr wollt den Affenkönig um ein Artefakt der Macht belauern, ich sorge dafür, dass Euch vergeht die Lust zum Kauern. Glaubt wohl, ein verfiddelter Knatzel zu sein, der sich auskennt beim Raufen, doch gegen die Mogu drehen sich viele nur noch um und laufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32335] = { id = 32335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der beste Streich", description = "Rätsel dreier an der Zahl löstet Ihr mir ohne Qual. Gut, gut. So alt, dass er jedem seine Tricks erzählen würde, ist der Affenkönig auch wieder nicht.\n\nDas war der tollste Streich, den ich mir je erlaubt habe!\n\nWollt Ihr die Geschichte vom Hammer und Affen hören? Zu schade, Ihr habt keine Wahl!", sourceObjective = "Hört Euch die Geschichte des Affenkönigs an.", completion = "Sieht so aus, als würde es ein paar Tage dauern, all diese \"Freunde\" aufzuspüren.\n\nDanke für Eure Hilfe, {name}. Trefft mich in ein paar Tagen in der Löwenlandung, und wir werden aufbrechen, um diese Objekte zu suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32336] = { id = 32336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Griff", description = "Es gab einst einen Häuptling namens Ingu Ingu,\n\nder mich bei einem Trink-Boogie besiegte.\n\nAls Siegertrophäe nahm er sich den Griff des Hammers,\n\nohne zu wissen, dass der König beim Trinken nicht besiegt werden kann.\n\nAffenkönig musste Hammer vor der Glocke verstecken,\n\naber Ingus Kinder gingen mit Griff nicht gut um.\n\nÜber die Jahre nutzten sie den Griff, um Schaden damit zu verursachen.\n\nJetzt müssen wir den heutigen Häuptling finden, um ihn zu entwaffnen.\n\nGeht nach Süden nach Unga Ingu. Dort Ihr Affenkönig treffen.\n\nNur Nappel kommen mit leeren Händen zu einem Fest.", sourceObjective = "Besorgt den Schlaghammergriff.", progress = "Ingu war ein toller Ho-zen. Guter Anführer, nette Feste und toller Fusel.", completion = "Artefakte machen Leute nicht großartig. Artefakte helfen Leuten, mehr sie selbst zu sein. Was gut ist, wird guter. Was schlecht ist, wird schlechterer. Und Häuptling Ingu Ingu wurde schlimmererer.", sourceObjectiveStatus = "unverified-source-field" }
quests[32337] = { id = 32337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kopf", description = "Affenkönig hat gehört, wo Kopf zu finden ist.\n\nDer Ho-zen, der ihn hatte, ist seit Langem tot. \n\nKunzen-Häuptlinge geben das Relikt vom Vater zum Sohn weiter, \n\naber dann kam Shed-Ling Skiggit und holte sich Kopf. \n\nJetzt betet der Nappel ihn in einer Höhle an. \n\nWeil er verfiddelterweise zu groß zum Schlucken war. \n\nHabe einen königlichen Finder nach Norden losgeschickt, um ihn aufzuspüren.\n\nHaltet in den Bergen westlich vom Kernland nach dem Finder Ausschau.", sourceObjective = "Besorgt den Schlaghammerkopf.", progress = "Ihr habt den Kopf?", completion = "Was Shed-Ling nicht verstehen, sie beten an, sie bekämpfen oder davor flüchten.\n\nIch ihnen ein paar Statuen von mir schicken sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[32338] = { id = 32338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die harmonische Salbe", description = "Legenden sind nicht geborene, sondern gemachte Dinge.\n\nWie auch Euer nächstes Ziel, ein Mogu namens \"Die Klinge\".\n\nIn seinen Taschen werdet Ihr finden,\n\neine Salbe, die den Verstand lässt sich winden.\n\nBringt diese Salbe zum König der Affen,\n\nmit ihr wird der mächtige Hammer erschaffen!\n\nReist entlang der Mauer nach Norden und biegt an deren Ende nach Links ab.", sourceObjective = "Besorgt die harmonische Salbe.", progress = "Wie die Mogu die Salbe finden konnten, grenzt an ein Wunder.\n\nAber seitdem die Welt auseinandergerissen wurde, ist viel passiert.", completion = "Juchhu!", sourceObjectiveStatus = "unverified-source-field" }
quests[32339] = { id = 32339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiederherstellung des Hammers", description = "Eins nach dem anderen!", sourceObjective = "Besorgt den Schlaghammer der Harmonie.", sourceObjectiveStatus = "unverified-source-field" }
quests[32340] = { id = 32340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plünderung des Schwarzen Tempels", description = "Während sich Akama und seine Männer um die Dämonen kümmern, hält Euch eigentlich nichts davon ab, das ein oder andere Relikt zu stehlen...", sourceObjective = "Plündert so viel Ihr nur könnt und gelangt zum Ende des Hofes der Irdischen Gelüste.", completion = "Ihr habt auf Eurem Weg nach oben alles geplündert, was Ihr nur konntet. Jetzt solltet Ihr Eure Beute zählen und sie verstecken, bevor Akama Euch einholt...", sourceObjectiveStatus = "unverified-source-field" }
quests[32341] = { id = 32341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellt Euer Können unter Beweis", description = "Akama und seine Männer werden von den Mächten belagert, die Ihr im Reliquiar der Seelen entfesselt habt.\n\nZeigt Akama, über welches Können Ihr verfügt, indem Ihr seine Männer vor den Dämonen rettet!", sourceObjective = "Vernichtet die Dämonen, die Akamas Männer in den Hallen der Pein angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32342] = { id = 32342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geisterfalle", description = "Wir haben mehrere mächtige Artefakte der Mogu in den Ruinen identifizieren können. In ihnen haben sie Geister eingefangen, die sie vermutlich bei einem Ritual oder einer Beschwörung einzusetzen beabsichtigten.\n\nEs handelt sich hier um ein Gerät, das wir bislang nicht identifizieren konnten und dringend erforschen müssen – die Artefakte könnten uns weiteren Aufschluss über die Geistbindungstechniken der Mogu geben. \n\nGeht und sucht ein paar Proben für uns, damit wir sie richtig untersuchen können.", sourceObjective = "Sammelt 3 Geisterfallen.", progress = "Habt Ihr die Fallen dabei?", completion = "Ahh, ja. Hmm. Gebt mal her. Vorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[32343] = { id = 32343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogudeis Leutnants", description = "Es gibt zwei extrem mächtige Mogugeister, welche die Allianz in ihrem Dilettantismus entfesselt hat.\n\nSie sind die idealen Ziele für uns, {class}. Wenn Ihr sie tötet und die Essenzen beider an Euch nehmt, könnte dies einen großen Fortschritt bei der Entschlüsselung der Geschichte dieser sonderbaren Ruine bedeuten.", sourceObjective = "Sammelt Meng-dos Essenz und Gen-lis Essenz in den Ruinen von Ogudei.", progress = "Die Essenz stellt sich nicht von selbst her, {race}!", completion = "Wahre Schätze sind das! Mit etwas Glück kehren die Geister wieder und wir können weitere Proben ihrer Essenz sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[32344] = { id = 32344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysteriös", description = "Wir haben in diesen Minen mehrere... Anomalien festgestellt, die arkaner oder spiritueller Natur sind. Sie vereiteln jegliche Versuche, die Art der Magie zu bestimmen, die hier für Rituale zur Geisterbindung eingesetzt wird.\n\nSie sind nur schwer zu fassen, aber wir konnten die arkane Signatur einer dieser Anomalien isolieren. Einer unserer Magier hat dieses Schmuckstück damit verzaubert.\n\nNehmt das Schmuckstück. Es wird immer heller leuchten, je weiter Ihr Euch der Anomalie nähert. Wenn Ihr sie erreicht, könnt Ihr das Schmuckstück einsetzen, um sie hinauszulocken.", sourceObjective = "Setzt das arkane Schmuckstück ein, um eine Anomalie in den Ruinen von Ogudei zu orten.", completion = "Ah, ja. Ich habe Nachricht von einem unserer Forscher, dass ihnen die Anomalie keinen Ärger mehr macht. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[32345] = { id = 32345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind keine Monster!", description = "Die Archäologische Akademie mag in der Vergangenheit einen schlechten Ruf gehabt haben, aber wir sind keine Monster. Wir vertreten lediglich andere Ansichten über die Archäologie als die Forscherliga.\n\nAb und zu widmen wir uns ganz der Vollbringung von Heldentaten. Also geht und befreit ein paar der Sklavengeister der Pandaren in den Ruinen.", sourceObjective = "Befreit 14 aufgewühlte Sklavengeister.", completion = "Ah, gute Arbeit. So trivial es angesichts unserer übergeordneten Forschungsziele auch erscheinen mag, es ist wichtig, dass wir den Schein wahren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[32346] = { id = 32346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich hab' keine Angst vor Gespenstern!", description = "Schaut, wir haben hier ein übles Problem, und der alte Trottmann drüben in der Löwenlandung schmeißt uns glatt raus, wenn wir hier nicht bald alles unter Kontrolle kriegen.\n\nHelft uns doch bitte!", sourceObjective = "Tötet 12 geistgebundene Mogu.", completion = "Jawoll! So werden wir schon gleich weitermachen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[32347] = { id = 32347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räumungsklage", description = "Diese verdammte Archäologische Akademie hat sich in die Ruinen geschlichen. Sie haben sich im unteren Bereich festgesetzt und treiben da unten allerhand magischen Schabernack.\n\nZeit, dass wir ihnen 'ne Räumungsklage an den Hals hängen, und zwar in Form eines Stiefels im Hinterteil!", sourceObjective = "Tötet 10 beliebige Anhänger der Archäologischen Akademie in den Ruinen von Ogudei.", completion = "Ha! Das sollte genügen, damit sie sich mit eingezogenem Schwanz nach Silbermond zurückziehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[32348] = { id = 32348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tretet sie, wenn sie am Boden liegen", description = "Dass sie ihre Basis in solcher Nähe eingerichtet hat, legt nahe, dass die Allianz denkt, sie habe die Ruinen fest in ihrem Würgegriff.\n\nDiese Fehleinschätzung werden wir ihr schon noch austreiben. Los, schaltet ein paar ihrer Wachen aus.", sourceObjective = "Tötet 12 Militäreinheiten der Löwenlandung.", completion = "Oh, was für ein herrlicher Tag. Diese Narren von der Allianz sind besiegt und unsere Forschungsarbeiten machen rasante Fortschritte.", sourceObjectiveStatus = "unverified-source-field" }
quests[32351] = { id = 32351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo des Donners", description = "Ah, {name}, so sieht man sich wieder. Ich habe erstaunliche Nachrichten.\n\nOberhäuptling Baine Bluthuf der Tauren ist in Pandaria eingetroffen.\n\nEr ist zu einem Treffen mit Kriegshäuptling Garrosh Höllschrei und dem Lordregenten Lor'themar Theron am Schrein der Zwei Monde im Tal der Ewigen Blüten unterwegs.\n\nEr sandte mir eine seltsame Bitte – ich soll ihm einen treuen Verfechter der Horde schicken, der des Kampfes fähig ist... und der Diskretion.\n\nIch kann mir niemand Besseren als Euch dafür vorstellen. Sprecht mit Tak-Tak, wenn Ihr eine Transportmöglichkeit sucht.", sourceObjective = "Findet Oberhäuptling Baine Bluthuf beim Schrein der Zwei Monde. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", completion = "Seid gegrüßt, {class}. Man hat Euch von der Herrschaftsfeste hergeschickt? Nun gut. Es gibt viel zu bereden.", sourceObjectiveStatus = "unverified-source-field" }
quests[32352] = { id = 32352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sturm zieht auf", description = "Wenn General Nazgrim Euch schickt, vertraue ich auf Eure Diskretion.\n\nAls ich hier ankam... experimentierte... Garrosh mit uralter Macht, die er in den Bergen im Norden gefunden hatte.\n\nEr glaubt, dass dieses \"Sha\" unsere Soldaten stärken kann.\n\nLeider legen die Resultate bislang die gegenteilige Wirkung nahe.\n\nUnsere Truppen scheinen ohne Sinn und Verstand gewalttätig zu werden. Geht und verhört sie. Verteidigt Euch, falls sie Euch bedrohen.", sourceObjective = "Nehmt es mit 6 Sha-berührten Grunzern auf.", progress = "Hier gibt es große Macht... Warum haben so viele davor Angst?", completion = "Ihr wart meinen Verteidigern überlegen? Endlich jemand, der seinen eigenen Hass und seine eigene Gewalt beherrschen kann!\n\nIch könnte mehr Leute wie Euch gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[32355] = { id = 32355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlaghammer der Harmonie", sourceObjective = "Findet Anduin Wrynn am Grab der Eroberer. Sprecht mit Fennie Hornsturz in der Löwenlandung für eine Transportmöglichkeit.", completion = "Ich bin froh, dass Ihr es geschafft habt. Ich könnte Eure Hilfe bei dem, was uns erwartet, gut gebrauchen. Meinem Vater wäre es lieber, ich würde in der sicheren Obhut seiner Legion bleiben.\n\nAber wenn mich Pandaria eines gelehrt hat, dann ist es die Tatsache, dass ein paar Leute zur richtigen Zeit am richtigen Ort mehr bewirken können als die größte Armee.", sourceObjectiveStatus = "unverified-source-field" }
quests[32356] = { id = 32356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Berufung der Botschafter", description = "Es wird Zeit, dass Sully und ich abreisen. Wir werden unsere Augen nach Hinweisen auf den Weißen Bauern offen halten und uns bald wieder melden.\n\nLeider muss ich Euch die Leitung überlassen, solange sich Admiral Taylor erholt. Lernt so viel Ihr nur könnt von diesen Jinyu, während wir fort sind. Ich erwarte bei unserer Rückkehr einen ausgiebigen Bericht.", sourceObjective = "Schickt die Späher los und sprecht dann mit dem Ältesten Lusshan.", sourceObjectiveStatus = "unverified-source-field" }
quests[32357] = { id = 32357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Ereignis abgeschlossen", description = "Es wird Zeit, dass Sully und ich abreisen. Wir werden unsere Augen nach Hinweisen auf den Weißen Bauern offen halten und uns bald wieder melden.\n\nLeider muss ich Euch die Leitung überlassen, solange sich Admiral Taylor erholt. Lernt so viel Ihr nur könnt von diesen Jinyu, während wir fort sind. Ich erwarte bei unserer Rückkehr einen ausgiebigen Bericht.", sourceObjective = "Schickt die Späher los und sprecht dann mit dem Ältesten Lusshan.", sourceObjectiveStatus = "unverified-source-field" }
quests[32358] = { id = 32358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenkern" }
quests[32359] = { id = 32359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge der Naaru", description = "Der Seelenkern hat sich zu einem Kristall gewandelt. Dies ist eindeutig das Artefakt, das Kanrethad und Jubeka erschaffen wollten, aber Ihr wisst noch immer nicht, wohin sie verschwunden sind.\n\nSucht den Schwarzen Prinzen in der Taverne im Nebel auf und seht, ob Ihr etwas über ihren Verbleib herausfinden könnt.", sourceObjective = "Bringt das Auge des Sturms zu Furorion in der Taverne im Nebel.", sourceObjectiveStatus = "unverified-source-field" }
quests[32360] = { id = 32360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warten auf die Schwarze Ernte", description = "{name}, von diesem Rat der Schwarzen Ernte habe ich noch nie gehört. Es beunruhigt mich jedoch sehr, dass sie an der Macht meines Vaters interessiert sind.\n\nIch habe jedoch... Kontakte, die uns helfen könnten, den Rat zu finden. Die meisten meiner Agenten sind mit dem Kampf zwischen der Allianz und Horde in Krasarang beschäftigt. Sobald sich die Lage dort beruhigt, werde ich Euch helfen.\n\nWenn Ihr wollt, könnt Ihr das Relikt der Naaru bei mir lassen, oder auch nicht – solange Ihr nicht als Leiche in einem Sumpf endet.", sourceObjective = "Wartet, bis Furorion mit Euch Kontakt aufnimmt.\n\n[In Patch 5.2 geht es weiter...]", sourceObjectiveStatus = "unverified-source-field" }
quests[32361] = { id = 32361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsereignis: Ereignis abgeschlossen", description = "Es wird Zeit, dass Sully und ich abreisen. Wir werden unsere Augen nach Hinweisen auf den Weißen Bauern offen halten und uns bald wieder melden.\n\nLeider muss ich Euch die Leitung überlassen, solange sich Admiral Taylor erholt. Lernt so viel Ihr nur könnt von diesen Jinyu, während wir fort sind. Ich erwarte bei unserer Rückkehr einen ausgiebigen Bericht.", sourceObjective = "Schickt die Späher los und sprecht dann mit dem Ältesten Lusshan.", sourceObjectiveStatus = "unverified-source-field" }
quests[32362] = { id = 32362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dalarans Schicksal", description = "Jaina weigert sich, mir zuzuhören. Vater hatte gehofft, ich könnte sie irgendwie beeinflussen, ich glaube jedoch, sie sieht mich immer noch als Kind.\n\nIhr seid aber <ein Held/eine Heldin> der Allianz und ich weiß, dass sie respektiert, was Ihr tut.\n\nGibt es etwas, das Ihr sagen könntet, um sie davon zu überzeugen, dass wir ihre Hilfe brauchen?", sourceObjective = "Sprecht mit Jaina Prachtmeer und hört Euch ihre Geschichte an.", progress = "Wir bitten nicht um militärische Streitkräfte. Doch wir sind auf Dalarans magische Unterstützung angewiesen, wenn wir Garroshs skrupellosen Feldzug aufhalten wollen.", completion = "Danke für Eure Hilfe. Ich höre die Weisheit in Jainas Worten.\n\nHoffentlich ist ihr Vertrauen in die Sonnenhäscher gerechtfertigt.", sourceObjectiveStatus = "unverified-source-field" }
